--
-- Estrutura para tabela `ordens_producao`
--

CREATE TABLE `ordens_producao` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `aluno_id` bigint(20) UNSIGNED DEFAULT NULL,
  `pedido_venda_id` bigint(20) UNSIGNED NOT NULL,
  `produto_acabado_id` bigint(20) UNSIGNED NOT NULL,
  `quantidade` int(11) NOT NULL,
  `quantidade_perda` int(11) NOT NULL DEFAULT 0,
  `status` varchar(255) NOT NULL DEFAULT 'Aberta',
  `embalado` tinyint(1) NOT NULL DEFAULT 0,
  `data_embalagem` timestamp NULL DEFAULT NULL,
  `status_material` varchar(255) NOT NULL DEFAULT 'Pendente',
  `data_inicio` date DEFAULT NULL,
  `data_inicio_real` datetime DEFAULT NULL,
  `data_fim` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `em_manutencao` tinyint(1) NOT NULL DEFAULT 0,
  `motivo_manutencao` text DEFAULT NULL,
  `previsao_conserto_ate` datetime DEFAULT NULL,
  `tem_refugo_forcado` tinyint(1) NOT NULL DEFAULT 0,
  `qtd_refugo_forcado` int(11) NOT NULL DEFAULT 0,
  `motivo_refugo_forcado` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

