(2, 'aluno.vendas.index', '1. SETOR DE VENDAS (Comercial)', '<h3>💰 Módulo Comercial: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO setor de Vendas é o <b>\"coração financeiro\"</b> e o ponto de partida de toda a Fábrica Digital. Nenhuma máquina liga e nenhum caminhão se move sem que haja um pedido registrado aqui. Sua missão é garantir que a carteira de pedidos esteja sempre ativa e que as datas prometidas aos clientes sejam realistas para não gerar multas ou atrasos.\n\n<b>🟢 Card: Abrir Venda (Registro de Ordem de Venda)</b>\n\nEste é o formulário de entrada de novos negócios. Siga o procedimento padrão:\n• <b>Seleção de Cliente:</b> Escolha um parceiro comercial cadastrado na sua carteira. Lembre-se: pedidos sem cliente não podem ser faturados futuramente.\n• <b>Data de Entrega Prometida:</b> Este é o campo mais crítico. Você deve prever um prazo que dê tempo para Compras adquirir o material, o WMS separar e a Produção fabricar. <b>Dica: Consulte o PCP antes de prometer prazos curtos!</b>\n• <b>Composição do Pedido:</b> Selecione o produto e a quantidade. Use o botão <b>[+ Adicionar Item]</b> para vendas complexas com múltiplos produtos.\n• <b>Cota de Vendas:</b> Fique atento ao indicador de cota diária. O Professor define quantos pedidos podem ser abertos por dia.\n• <b>Finalização:</b> Ao clicar em <b>[Finalizar Pedido]</b>, revise o volume total no modal. Uma vez transmitido, o pedido segue para o PCP.\n\n<b>🔵 Card: Gerenciar Carteira (Monitoramento de Status)</b>\n\nAqui você acompanha o ciclo de vida de cada venda realizada:\n• <b>ID do Pedido:</b> Identificação única para rastreio em toda a fábrica.\n• <b>Data de Entrega (Cor Crítica):</b> Se estiver em <b>Preto</b>, está no prazo. Se estiver em <b>Vermelho/Piscando</b>, o pedido está atrasado.\n• <b>Status Operacional:</b>\n<b>Novo:</b> Aguardando o PCP gerar as ordens.\n<b>Em Produção:</b> O chão de fábrica já está trabalhando.\n<b>Faturado:</b> Pedido entregue e receita garantida.\n\n<b>🧠 Dicas do Mestre (Estratégia Industrial)</b>\n<b>Não \"sufoque\" a fábrica:</b> Abrir muitos pedidos sem estoque trava o Almoxarifado e gera custos extras de urgência.\n\n<b>Acompanhe o Monitor:</b> Use o botão <b>[📺 MONITOR]</b> para identificar onde seus pedidos estão parados.\n<b>Refugo e Atraso:</b> Refugos na produção atrasam sua entrega. Comunique-se com a Produção para renegociar prioridades.\n\n<b>🔗 Conexão entre Setores</b>\n• <b>Você recebe dados de:</b> Clientes e Engenharia (Produtos).\n• <b>Você envia dados para:</b> <b>PCP</b> (Necessidade de Demanda).\n\nManual da Fábrica Digital - Documentação Técnica Comercial', '2025-12-31 01:37:33', '2026-01-09 22:28:37'),
(3, 'aluno.pcp.dashboard', '2. SETOR DE PCP (Planejamento)', '<h3>📊 Módulo PCP: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO PCP (Planejamento e Controle da Produção) é o <b>\"Cérebro\"</b> da Fábrica Digital. Sua função é traduzir os pedidos do Comercial em ordens reais de fabricação e compra. O PCP garante que a fábrica tenha material disponível e que a produção respeite a capacidade técnica das máquinas.\n\n<b>🔵 Card: Vendas (Análise de Demanda Bruta)</b>\n\nNesta tela, você processa os pedidos fechados pelo Comercial:\n• <b>Análise de MRP:</b> O sistema calcula a necessidade de materiais (BOM) para cada produto vendido.\n• <b>Gerar Ordens:</b> Ao processar um pedido, você dispara automaticamente a <b>OP (Ordem de Produção)</b> para a Fábrica e a <b>OC (Ordem de Compra)</b> para o Suprimentos.\n\n<b>🟠 Card: Produção (Gestão de Carga e Capacidade)</b>\n\nMonitoramento do status do chão de fábrica:\n• <b>Status Operacional:</b> Acompanhe se a ordem está <b>Aberta</b> (esperando material), <b>Em Produção</b> (máquina ligada) ou <b>Concluída</b>.\n• <b>Capacidade Fabril:</b> Evite acumular muitas ordens \"Abertas\". Isso indica falta de material ou gargalo na linha.\n\n<b>🟣 Card: Suprimentos (Status de Abastecimento)</b>\n\nMonitoramento da chegada de materiais:\n• <b>Status de OC:</b> Verifique se as compras estão <b>Pendentes</b>, <b>Aguardando Entrega</b> ou <b>Concluídas</b> (disponíveis no estoque). Sem material concluído, a produção não inicia.\n\n<b>🧠 Dicas do Mestre (Estratégia Industrial)</b>\n\n<b>Sincronismo:</b> Não gere OPs se o setor de Compras estiver travado. Monitore o abastecimento para evitar máquinas paradas.\n<b>Prioridade Máxima:</b> Use o <b>Monitor</b> para identificar pedidos com data de entrega crítica e priorize essas ordens no PCP.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Vendas</b> (Pedidos Novos).\n• <b>Você envia dados para:</b> <b>Produção</b> (Comando de fabricação) e <b>Compras</b> (Necessidade de insumos).\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-09 21:56:04', '2026-01-09 22:28:07'),
(4, 'aluno.compras.dashboard', '3. SETOR DE COMPRAS (Suprimentos)', '<h3>🛒 Módulo de Compras: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO setor de Compras e Suprimentos é o braço logístico-financeiro da empresa. Sua função é transformar as necessidades de materiais enviadas pelo PCP em pedidos reais para os fornecedores. O sucesso aqui é medido pela habilidade de comprar pelo <b>menor preço</b> e garantir que o material chegue no <b>menor prazo</b> possível para não interromper a produção.\n\n<b>🟢 Card: Realizar Cotações (Novas Solicitações)</b>\n\nAqui aparecem as demandas geradas pelo PCP. Cada linha é um pedido de socorro do chão de fábrica:\n• <b>Análise de Prioridade:</b> Itens marcados como \"Urgente\" (geralmente reposições de refugo) devem ser sua prioridade absoluta.\n• <b>Homologação de Fornecedores:</b> Ao clicar em confirmar, você deverá escolher o fornecedor. Compare sempre o custo unitário versus o prazo de entrega.\n• <b>Efetivação:</b> Uma vez confirmada a compra, a responsabilidade de Compras encerra e o material entra em fluxo logístico (transporte).\n\n<b>🟡 Card: Log de Ocorrências (Gestão de Recusas)</b>\n\nEste é o \"Hospital\" das compras. Aqui aparecem os materiais que o <b>Almoxarifado (WMS) recusou</b> no momento do recebimento (por avaria, erro de nota ou sabotagem do professor).\n• <b>Status Resolvido:</b> Indica que a tratativa de devolução foi feita e o processo foi encerrado.\n• <b>Recompra:</b> Se o WMS recusou, a produção vai parar! Você deve gerar uma nova compra urgente imediatamente para repor o item rejeitado.\n\n<b>🔵 Card: Histórico de Pedidos (Rastreabilidade)</b>\n\nPainel de controle de todas as Ordens de Compra (OC) que já foram aceitas por você:\n• <b>Previsão de Entrega:</b> Use esta data para informar ao PCP quando o material estará disponível.\n• <b>Status Logístico:</b>\n<b>Aguardando Entrega:</b> O material está no caminhão em trânsito para a fábrica.\n<b>Concluído:</b> O material já foi recebido pelo WMS e está na prateleira pronto para uso.\n\n<b>🧠 Dicas do Mestre (Estratégia de Suprimentos)</b>\n\n<b>Custo de Urgência:</b> Evite compras urgentes. Elas costumam sinalizar falha de planejamento no PCP ou excesso de refugo na Produção.\n<b>Gestão de Estoque:</b> Se o Monitor mostrar que um pedido está parado em \"COMP\", a ação depende de você. Agilize a cotação!\n<b>Fornecedores Globais:</b> Fique atento a fornecedores que entregam em 0 dias (estoque imediato), eles são seus melhores aliados em momentos de crise.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>PCP</b> (Solicitações de Compra) e <b>WMS</b> (Alertas de Recusa).\n• <b>Você envia dados para:</b> <b>WMS</b> (Caminhão na Doca) e <b>Produção</b> (Disponibilidade de insumos).\n\nManual da Fábrica Digital - Documentação Técnica de Suprimentos', '2026-01-09 22:04:42', '2026-01-09 22:32:24'),
(5, 'aluno.almoxarifado.dashboard', '4. SETOR DE WMS (Almoxarifado)', '<h3>📦 Módulo WMS: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO WMS (Warehouse Management System) é o guardião físico da Fábrica Digital. Sua responsabilidade é gerenciar a entrada, a organização (endereçamento) e a saída de materiais para o abastecimento das máquinas. Um Almoxarifado eficiente garante que a produção nunca pare por falta de insumos e que o inventário reflita exatamente o que existe nas prateleiras.\n\n<b>🟡 Card: Checklist de Entrada (Conferência)</b>\n\nÉ o portal de entrada da fábrica. Quando um fornecedor entrega um material, ele aparece na sua <b>Doca de Recebimento</b>.\n• <b>Conferência Física:</b> Verifique se a quantidade e o material na OC (Ordem de Compra) batem com o que chegou no caminhão.\n• <b>Fluxo de Decisão:</b>\n<b>Receber:</b> Se tudo estiver OK, o material entra no sistema com status \"No Chão\" (aguardando guardagem).\n<b>Recusar:</b> Se o Professor injetou uma <b>Inconformidade</b>, o botão Receber estará bloqueado. Você deve clicar em Recusar e descrever o laudo técnico para que o setor de Compras providencie a reposição urgente.\n\n<b>🔵 Card: Consulta de Inventário (Saldo e Auditoria)</b>\n\nSua ferramenta de controle para garantir a acuracidade do estoque:\n• <b>Saldo Físico:</b> Mostra a quantidade real de cada material que a empresa possui.\n• <b>Endereço (WMS):</b> Indica exatamente em qual Rua, Vão e Nível o material está guardado. Se o campo estiver vazio, o material está parado no pátio e não pode ser usado pela Produção.\n\n<b>🟣 Card: Mapa de Armazenagem (Gestão de Coordenadas)</b>\n\nO coração visual do setor. Aqui você organiza a estrutura vertical da empresa:\n• <b>Guardar Material:</b> Materiais que acabaram de ser recebidos aparecem na lista de espera. Escolha uma prateleira livre (Verde) e clique em <b>[Guardar Aqui]</b> para oficializar o endereço.\n• <b>Ocupação:</b> O mapa permite visualizar o nível de lotação da fábrica. Mantenha o fluxo de entrada e saída equilibrado para não faltar espaço.\n\n<b>🔵 Card: Pedidos da Produção (Picking List)</b>\n\nA operação de saída interna do armazém para abastecer as máquinas:\n• <b>Localizar Insumos:</b> O sistema indica em qual prateleira o material solicitado pelo operador de máquina se encontra.\n• <b>Confirmar Separação:</b> Ao concluir o picking, o saldo do estoque baixa automaticamente e o material é entregue na Produção, autorizando o início da fabricação.\n\n<b>🧠 Dicas do Mestre (Estratégia Logística)</b>\n\n<b>Fim do Estoque no Chão:</b> Nunca deixe materiais recebidos sem endereço por muito tempo. Materiais sem local definido no mapa não aparecem na lista de Picking, o que trava a linha de Produção.\n<b>Acuracidade é Lei:</b> Se o Monitor mostrar atraso na Produção por \"Falta de Material\" e você tiver saldo no inventário, verifique se não esqueceu de confirmar a separação de uma lista pendente.\n<b>Organização Visual:</b> No mapa, prateleiras vermelhas estão ocupadas. Planeje o endereçamento para facilitar a retirada rápida dos materiais mais usados (Curva ABC).\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Compras</b> (Caminhão na Doca) e <b>Produção</b> (Solicitações de Insumos).\n• <b>Você envia dados para:</b> <b>Produção</b> (Liberação de matéria-prima) e <b>Compras</b> (Alertas de materiais rejeitados).\n\nManual da Fábrica Digital - Documentação Técnica de Logística e WMS', '2026-01-09 22:44:19', '2026-01-09 22:44:19'),
(6, 'aluno.producao.dashboard', '5. SETOR DE PRODUÇÃO (Chão de Fábrica)', '<h3>🏭 Módulo de Produção: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO setor de Produção é onde a mágica da transformação acontece. É o \"músculo\" da Fábrica Digital. Sua responsabilidade é operar as máquinas para transformar matéria-prima em produtos acabados, respeitando rigorosamente os prazos do cliente e mantendo o mais alto nível de qualidade, evitando o desperdício de materiais (Refugo).\n\n<b>⬛ Card 1: Ordens Disponíveis (Backlog)</b>\n\nAqui estão listados todos os comandos de fabricação enviados pelo PCP que ainda não possuem um operador atribuído:\n• <b>Assumir Ordem:</b> Escolha uma ordem na fila e clique para trazê-la para sua responsabilidade.\n• <b>Capacidade de Carga:</b> Fique atento ao indicador no canto do card (ex: 0/4). O Professor define o limite máximo de ordens que cada aluno pode processar simultaneamente para evitar sobrecarga na linha\n.\n<b>🟦 Card 2: Linhas de Produção Ativas (Seu Posto de Trabalho)</b>\n\nEste é o seu painel operacional. Cada ordem assumida passará por um ciclo obrigatório:\n• <b>Solicitar Material:</b> Antes de ligar a máquina, você deve pedir os insumos ao Almoxarifado. O sistema calculará a necessidade baseada na receita do produto.\n• <b>Iniciar Produção:</b> Este botão só será liberado após o WMS confirmar a entrega física do material na sua linha. Ao clicar, o cronômetro de Lead Time da simulação começa a rodar.\n• <b>Finalizar e Apontar:</b> No término do processo, você deve registrar o resultado:\n<b>Caminho Feliz:</b> Se a máquina operou normal, você apenas confirma a entrada do lote total no estoque.\n<b>Caminho do Caos:</b> Se o Professor injetou uma falha técnica, você verá um \"Laudo de Falha\" e será obrigado a aceitar o refugo programado, disparando uma reposição automática de material.\n\n<b>⬜ Card: Qualidade & Refugo (Histórico e Perdas)</b>\n\nAcesso direto ao banco de dados de produtividade da sua equipe:\n• <b>Histórico de Apontamentos:</b> Verifique quem produziu, em qual data e qual foi o índice de aproveitamento de cada lote.\n• <b>Rastreio de Perdas:</b> Analise os motivos técnicos que geraram refugo para evitar que o erro se repita em ordens futuras.\n\n<b>🧠 Dicas do Mestre (Estratégia Fabril)</b>\n\n<b>Gargalo de Material:</b> Se o status estiver em \"Solicitado\" por muito tempo e a máquina não liga, o material está parado no Almoxarifado.\n\nUse o <b>[📺 MONITOR]</b> para cobrar agilidade do setor logístico.\n<b>Inteligência de Reposição:</b> Caso ocorra refugo, não se preocupe com cálculos. Ao clicar em \"Solicitar Material\" novamente, o sistema pedirá <b>apenas o saldo que falta</b> para completar o pedido original.\n<b>Manutenção Preventiva:</b> Máquinas em manutenção (ícone de fogo 🔥 no monitor) param a produção por dias. Planeje sua carga de trabalho em outras OPs enquanto aguarda o conserto.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>PCP</b> (Ordens de Produção) e <b>WMS</b> (Insumos Físicos).\n• <b>Você envia dados para:</b> <b>Embalagem</b> (Lotes Prontos) e <b>WMS/Compras</b> (Solicitações de reposição de insumos).\n\nManual da Fábrica Digital - Documentação Técnica de Produção', '2026-01-09 22:48:34', '2026-01-09 22:54:03'),
(7, 'professor.monitoramento.embalagem', '6. SETOR DE EMBALAGEM (Packing & Consolidação)', '<h3>🎁 Módulo de Embalagem: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO setor de Embalagem é o posto de controle final da qualidade física do produto. Sua função é receber os lotes concluídos na Produção e realizar a conferência rigorosa de cada componente antes de lacrar a embalagem definitiva. Este setor garante que o cliente receba exatamente o que comprou, sem peças faltando ou erros de montagem.\n\n<b>🟢 Card: Estação de Embalagem (Controle de Lotes)</b>\n\nCada produto que sai da linha de montagem aparece automaticamente na sua esteira de empacotamento:\n• <b>Status de Produção:</b> Verifique se a quantidade produzida atende à meta da Ordem de Produção (ex: 5/5). Se o lote estiver incompleto devido a refugo, o sistema bloqueará o lacre até que a reposição seja concluída.\n• <b>Checklist de Materiais (Status WMS):</b> Confirme se todos os insumos necessários (BOM) foram devidamente entregues pelo Almoxarifado. O sistema sinaliza com um \"✓\" os materiais disponíveis.\n• <b>Conferência Física:</b> Você deve marcar manualmente cada item da lista para validar que as peças estão fisicamente na mesa de embalagem.\n\n<b>🟢 Botão: Lacrar Lote / Embalar</b>\n\nEsta é a ação que oficializa a entrada do produto no estoque final:\n• <b>Validação:</b> O botão só será habilitado após todos os itens do checklist serem marcados e a produção estar 100% concluída.\n• <b>Entrada no Estoque:</b> Ao clicar em <b>[Lacrar Lote]</b>, as unidades produzidas saem da \"Esteira\" e entram no saldo de Produtos Acabados da empresa, ficando disponíveis para a Expedição faturar.\n\n<b>🧠 Dicas do Mestre (Estratégia de Qualidade)</b>\n\n<b>Gargalo na Esteira:</b> Se houver muitos lotes acumulados \"Dormindo\" na embalagem, a Expedição não terá o que vender, travando o faturamento da empresa. Mantenha o fluxo constante!\n<b>Lote Incompleto:</b> Caso veja a mensagem \"Lote Incompleto (Refugo)\", saiba que a Produção ainda está aguardando material de reposição do WMS. Você não pode embalar \"meio produto\".\n\n<b>Monitoramento:</b> Use o <b>[📺 MONITOR]</b> para prever quais OPs estão em fase final de montagem e prepare suas embalagens e etiquetas com antecedência.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Produção</b> (Lotes Concluídos) e <b>WMS</b> (Status de entrega de insumos).\n• <b>Você envia dados para:</b> <b>Expedição</b> (Saldo de estoque pronto para faturamento).\n\nManual da Fábrica Digital - Documentação Técnica de Embalagem', '2026-01-09 22:53:13', '2026-01-09 22:53:13'),
(8, 'aluno.expedicao.dashboard', '7. SETOR DE EXPEDIÇÃO (Faturamento e Saída)', '<h3>🚚 Módulo de Expedição: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO setor de Expedição é a última fronteira da Fábrica Digital. Sua missão é realizar o <b>faturamento</b> (emissão de Nota Fiscal), a <b>baixa definitiva do estoque</b> e o <b>embarque</b> dos produtos para o cliente final. É o momento em que a operação industrial se transforma oficialmente em receita financeira para a empresa.\n\n<b>📦 Card: Dock de Saída (Conferência e Embarque)</b>\n\nNeste local, ficam listados os pedidos que já passaram pela Embalagem e estão 100% prontos para o envio:\n• <b>Status de Prazo:</b> Monitore as etiquetas de atraso (em vermelho). Pedidos que ultrapassam a \"Data Prometida\" prejudicam o indicador de Nível de Serviço (OTIF) nos relatórios de BI.\n• <b>Conferência de Estoque:</b> Antes de faturar, o sistema valida se as peças produzidas e embaladas entraram corretamente no saldo de Produtos Acabados.\n• <b>Ação [CONFERIR]:</b> Ao clicar neste botão, você revisa os volumes e confirma o faturamento. Nesse instante, o sistema emite a Nota Fiscal e remove os itens do inventário físico.\n\n<b>📄 Card: Histórico de NFs (Arquivo Fiscal)</b>\nO repositório de todos os documentos legais emitidos pela sua empresa:\n• <b>Rastreabilidade:</b> Acesse o número da nota, a data exata da emissão e o valor total da venda.\n• <b>Chave de Acesso:</b> Cada operação gera uma chave eletrônica única, garantindo a integridade do processo simulado.\n• <b>Visualização do DANFE:</b> Use esta tela para visualizar o documento final que acompanha a mercadoria, contendo o código de barras e os dados do cliente.\n\n<b>🧠 Dicas do Mestre (Estratégia Logística)</b>\n\n<b>Sincronismo com Embalagem:</b> Se o <b>[📺 MONITOR]</b> indicar que a produção terminou, mas o pedido não aparece no seu Dock de Saída, significa que o setor de Embalagem ainda não lacrou o lote.\n<b>Agilidade no Faturamento:</b> O lucro da empresa só é contabilizado no BI após a emissão da Nota Fiscal. Deixar pedidos parados no Dock de Saída \"esconde\" o resultado real da equipe.\n<b>Bloqueios de TI:</b> Fique atento ao Painel do Caos. Se o sistema de faturamento for sabotado pelo Professor (Queda de TI), você ficará impossibilitado de emitir notas até que o tempo avance ou o problema seja resolvido.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Embalagem</b> (Lotes Consolidados) e <b>Estoque</b> (Saldo de Produtos Prontos).\n• <b>Você finaliza o ciclo:</b> O pedido recebe o status final de <b>Faturado</b> e a receita é enviada para a Visão Executiva (BI).\n\nManual da Fábrica Digital - Documentação Técnica de Expedição', '2026-01-09 22:58:42', '2026-01-09 22:58:42'),
(9, 'aluno.gestao_vista', 'PAINEL DE GESTÃO À VISTA (Monitoramento Andon)', '<h3>📺 Painel de Gestão à Vista: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Painel de Gestão à Vista é a <b>\"Torre de Controle\"</b> central da Fábrica Digital. Inspirado no conceito japonês de <b>Andon</b>, este monitor traduz dados complexos em sinais visuais simples (luzes e cores). Sua função é permitir que tanto o Professor quanto os Alunos visualizem, em uma única tela, onde cada pedido está travado e qual o nível de saúde de toda a operação industrial em tempo real.\n\n<b>⬛ Tabela: Monitor de Produção em Tempo Real</b>\nAqui estão listados todos os pedidos que entraram no sistema e ainda estão em processamento:\n• <b>Identificação (ID):</b> Clique no número do pedido (ex: #34) para abrir a <b>Ficha de Rastreabilidade</b>. Ela revela o \"DNA\" do pedido, mostrando exatamente quais matérias-primas foram compradas, se houve recusa no WMS ou se a máquina gerou refugo.\n• <b>Agrupamento por Cores:</b> Pedidos que contêm vários produtos diferentes compartilham a mesma cor de fundo. Isso ajuda a identificar visualmente que aquele bloco de linhas pertence ao mesmo cliente e deve ser faturado junto.\n• <b>Status Operacional:</b> Indica a fase atual da Ordem de Produção (Aberta, Em Produção ou Concluída). Se houver refugo, o sistema exibirá o alerta de <b>🚨 REPOSIÇÃO</b>.\n• <b>Barra de Entrega:</b> Um cronômetro visual que monitora o prazo.\n<b>Verde:</b> Operação dentro do prazo.\n<b>Vermelho/Piscando:</b> Pedido em atraso em relação à Data do Jogo.\n\n<b>⬜ Tabela: Arquivo Morto (Histórico Concluído)</b>\nLocalizada na parte inferior da tela, esta tabela em tons de cinza armazena o rastro dos últimos pedidos que foram faturados:\n• <b>Memória de Fluxo:</b> Mesmo após o faturamento, você pode clicar no ID para analisar como foi o processo daquela venda (se houve muitas intercorrências de Caos ou se o fluxo foi limpo).\n• <b>Data de Finalização:</b> Registra o momento exato do jogo em que a nota fiscal foi emitida.\n\n<b>🧠 Dicas do Mestre (Torre de Controle)</b>\n\n<b>Rastreio de Inconformidade:</b> Ao abrir o detalhe de um pedido, observe os ícones dos setores. Se o ícone da <b>Produção (🏭)</b> ou <b>Compras (🚚)</b> estiver piscando em vermelho, há um problema crítico de refugo ou recusa que precisa de atenção imediata.\n<b>Sincronismo Total:</b> Use este painel para identificar gargalos. Se você vê muitos pedidos parados em \"WMS\", o almoxarifado é o seu ponto fraco no momento.\n<b>Análise de Causa Raiz:</b> Na tabela de insumos dentro do monitor, o sistema indica a <b>Origem (Causa)</b> da compra. Isso ajuda o Professor a avaliar se o aluno de compras está gastando dinheiro para repor erros do WMS (Recusas) ou da Produção (Refugo).\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>O Monitor consome dados de:</b> <b>Vendas, PCP, Compras, WMS, Produção e Embalagem.</b>\n• <b>O Monitor envia informações para:</b> Toda a Fábrica, servindo como a bússola para a tomada de decisão de todos os gestores.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-09 23:03:04', '2026-01-09 23:03:04'),
(10, 'professor.turmas.perfil', 'PERFIL CORPORATIVO (Identidade da Empresa)', '<h3>🏢 Perfil Corporativo: Roteiro de Visualização</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Perfil Corporativo é a <b>\"Certidão de Nascimento\"</b> da sua empresa. Nesta tela, todos os colaboradores podem consultar a identidade jurídica e estratégica da organização. Ela define o propósito da fábrica, sua localização física e sua posição no mercado. Ter uma missão clara ajuda a guiar as decisões de todos os departamentos em direção aos objetivos da gerência.\n\n<b>🟣 Cabeçalho: Registro de Atividade Industrial</b>\n\nA parte superior do card identifica os dados mestres da empresa:\n\n• <b>Nome da Unidade:</b> O nome fantasia da sua fábrica (Ex: BETA).\n• <b>Setor e Segmento:</b> Define em qual mercado a empresa atua. Caso apareça como \"Não Definido\", significa que a estratégia de nicho ainda não foi oficializada pelo Professor.\n\n<b>📄 Card: Resumo e Missão</b>\nEste campo descreve a <b>alma da empresa</b>.\n• <b>Propósito:</b> Aqui deve constar o que a empresa faz e quais são seus valores. É um campo fundamental para a imersão no jogo, transformando a turma em uma corporação real com objetivos de mercado definidos.\n\n<b>📍 Card: Dados Legais e Localização</b>\nInformações de contato e registro para fins de faturamento e logística:\n• <b>CNPJ e Contato:</b> Dados necessários para a formalização de compras e vendas.\n• <b>Endereço da Unidade:</b> A localização geográfica da fábrica. Esses dados são utilizados automaticamente pelo sistema para compor o cabeçalho das suas <b>Notas Fiscais (DANFE)</b> no setor de Expedição.\n\n<b>🧠 Dicas do Mestre (Identidade de Marca)</b>\n<b>Visualização Restrita:</b> Note que esta tela é de <b>Apenas Leitura</b> para os alunos. Somente o Professor (Game Master) possui as credenciais para alterar o nome, endereço ou CNPJ da organização.\n<b>Imersão:</b> Leia atentamente a \"Missão\" da sua empresa. Ela pode conter pistas sobre o nível de exigência de qualidade ou sobre a prioridade de atendimento que o Professor espera da sua equipe.\n<b>Documentação:</b> Verifique se o endereço está correto, pois ele aparecerá em todos os documentos impressos e digitais gerados pela sua operação logística.\n\n<b>🔗 Conexão entre Setores</b>\n• <b>Você recebe dados de:</b> <b>Professor (Gerência)</b>, que configura a identidade da turma.\n• <b>Você envia dados para:</b> <b>Expedição e Vendas</b>, alimentando os dados de cabeçalho das Notas Fiscais e Pedidos.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-09 23:14:03', '2026-01-09 23:15:04'),
(11, 'professor.monitoramento.bi', 'TORRE DE CONTROLE (Business Intelligence - BI)', '<h3>🚀 Torre de Controle: Roteiro Completo de Indicadores</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA Torre de Controle é a central de inteligência do <b>Professor (Game Master)</b>. Ela não apenas exibe números, mas interpreta o comportamento da fábrica. Cada gráfico e caixa de índice atua como um sensor em tempo real, permitindo diagnosticar se a empresa está sendo lucrativa, eficiente ou se está perdendo dinheiro por falhas operacionais.\n\n<b>📊 Aba 1: Visão Executiva (Saúde Financeira)</b>\nEsta aba consolida os indicadores de alto nível para a tomada de decisão da gerência:\n• <b>Caixas de Receita e Lucro:</b> Atuam comparando o <b>Faturamento Real</b> (Notas Fiscais emitidas) com o <b>Custo Operacional</b> (Perdas e Compras). O índice de Lucro Líquido desconta automaticamente 10% de impostos para simular a carga tributária real.\n• <b>Capital em Estoque:</b> Este índice soma o valor financeiro de toda a matéria-prima e produtos acabados parados nas prateleiras. Ele serve para alertar sobre o \"dinheiro parado\" que não está gerando lucro.\n• <b>Gráfico Faturamento (Realizado vs Meta):</b> Atua comparando o que já foi faturado (Barra Verde) com o que está em carteira (Barra Preta). Se a meta for muito maior que o realizado, a expedição está lenta.\n• <b>Gargalo de Produção:</b> Gráfico circular que rastreia em qual status as Ordens de Produção estão acumuladas (Abertas, Em Produção ou Concluídas).\n\n<b>💰 Aba 2: Comercial (Performance de Vendas)</b>\n\nFocada na análise da carteira de clientes e produtos:\n• <b>Curva ABC de Produtos:</b> Atua aplicando a regra de Pareto (80/20). Ela classifica os produtos em Classe A (mais valiosos), B ou C, permitindo identificar quais produtos sustentam o faturamento da empresa.\n• <b>Funil de Pedidos:</b> Um gráfico de barras horizontais que mostra o fluxo comercial, desde a abertura do pedido até o faturamento. Ele indica se o comercial está vendendo mais do que a fábrica consegue entregar.\n• <b>Ticket Médio:</b> Calcula o valor médio por venda, servindo para avaliar o perfil dos clientes atendidos.\n\n<b>🏭 Aba 3: Indústria (Eficiência e Qualidade)</b>\n\nMonitora o que acontece dentro da fábrica e no setor de compras:\n• <b>Custo da Ineficiência (Caos):</b> Uma caixa de alerta que soma o prejuízo real de cada peça de refugo e cada carga recusada no WMS. É o índice que mede o impacto financeiro direto das sabotagens do professor.\n• <b>Taxa de Refugo:</b> Gráfico de pizza que confronta peças boas versus descartadas. Atua medindo a precisão da operação manual do aluno na produção.\n• <b>Spend Analysis:</b> Gráfico de barras que atua mapeando o destino do dinheiro de Compras, listando os insumos que mais consomem o orçamento da empresa.\n• <b>Qualidade do Fornecedor:</b> Índice percentual que mede a confiabilidade das entregas (Entregas Aceitas vs Recusadas).\n\n<b>🚚 Aba 4: Logística & WMS (Gestão de Fluxo)</b>\n\nAvalia a movimentação física de materiais:\n• <b>Ocupação do Armazém:</b> Gráfico de rosca que indica o percentual de prateleiras utilizadas no mapa 3D. Se chegar a 100%, o recebimento é bloqueado.\n• <b>Giro de Estoque e Acuracidade:</b> Barras de progresso que medem a velocidade de saída dos materiais e a precisão entre o saldo do sistema e o saldo físico nas gavetas.\n• <b>Doca de Saída:</b> Um contador de alta visibilidade que mostra quantos pedidos já estão embalados e \"gritam\" por faturamento imediato.\n\n<b>🧠 Dicas do Mestre (Análise de Dados)</b>\n\n<b>O Relógio é o Guia:</b> O cabeçalho exibe a <b>Data da Simulação</b>. Todos os dados financeiros e produtivos são sincronizados com esse tempo virtual, e não com o tempo real do seu computador.\n<b>Filtro de Período:</b> Use o calendário no topo para comparar a performance entre \"meses\" virtuais do jogo. Isso permite ver se a equipe melhorou ou piorou após uma crise injetada.\n<b>Equilíbrio OEE:</b> O índice OEE (Eficiência Global) é o mais difícil de manter alto. Ele exige que o PCP planeje bem, as Compras entreguem no prazo e a Produção não gere refugo.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Entrada:</b> Coleta dados de Notas Fiscais (Vendas), Apontamentos (Produção), OCs (Compras) e Ocupação (WMS).\n• <b>Saída:</b> Fornece o diagnóstico final para o <b>Professor</b> avaliar o desempenho técnico e comportamental de cada grupo de alunos.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-09 23:22:20', '2026-01-09 23:23:51'),
(12, 'professor.materias-primas.index', 'CADASTRO DE MATÉRIAS-PRIMAS (Insumos)', '<h3>📦 Módulo de Matérias-Primas: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA gestão de Matérias-Primas é a fundação de toda a cadeia produtiva. Sem o cadastro correto dos insumos, o PCP não consegue planejar a receita dos produtos e o setor de Compras não consegue realizar cotações. Esta tela é uma ferramenta híbrida: enquanto o <b>Aluno</b> foca nos materiais de sua unidade, o <b>Professor</b> atua na padronização global e na supervisão de todos os estoques da simulação.\n\n<b>🟣 Card: Cadastrar Novo Insumo (Registro de Entrada)</b>\n\nAqui é definida a identidade técnica de cada componente que entrará na fábrica:\n• <b>Empresa Detentora:</b> Define quem \"somos\" neste registro.\n<b>Global:</b> Disponível para todas as fábricas do simulador.\n<b>Empresa Específica:</b> O material pertence apenas a uma turma, permitindo simular insumos exclusivos.\n• <b>SKU (Código):</b> Identificador único do material (Ex: MP-001). Use códigos lógicos para facilitar a busca no Almoxarifado.\n• <b>Nome do Material:</b> Descrição clara do item (Ex: Prancha de Madeira, Eixo de Aço).\n• <b>Unidade:</b> Define a métrica de controle (kg, un, lt, m). Lembre-se: o PCP usará esta unidade para calcular o consumo na produção.\n\n<b>🟡 Card: Inventário de Matérias-Primas (Gestão de Dados)</b>\n\nA tabela central de consulta e auditoria dos registros:\n• <b>Filtro de Empresa:</b> O Professor pode alternar entre <b>\"Todas as Empresas\"</b> para uma visão de administrador ou filtrar uma turma específica. O Aluno visualiza apenas o que é pertinente à sua operação.\n• <b>Ações Técnicas:</b>\n<b>Editar:</b> Permite corrigir nomes ou unidades.\n<b>Excluir:</b> Remove o material da lista ativa. O sistema utiliza <b>Soft Deletes</b>, preservando o histórico de compras e produções antigas no banco de dados.\n\n<b>🧠 Dicas do Mestre (Estratégia de Engenharia)</b>\n<b>Padronização de SKU:</b> Evite criar SKUs genéricos como \"001\". Prefira nomenclaturas que identifiquem a família do produto, como \"MET-01\" para metais, facilitando a organização visual no Mapa WMS.\n<b>Cuidado com a Unidade:</b> Mudar a unidade de medida após o início do jogo pode causar erros de cálculo no MRP. Defina a métrica correta no momento do cadastro.\n<b>Visão Global:</b> Materiais globais economizam tempo de cadastro, mas materiais específicos permitem que o Professor crie cenários de escassez para testar a negociação entre os alunos.\n\n<b>🔗 Conexão entre Setores</b>\n• <b>Você recebe dados de:</b> <b>Professor / Engenharia</b> (Definição de insumos necessários).\n• <b>Você envia dados para:</b> <b>PCP</b> (Para compor a BOM/Receita) e <b>Compras</b> (Para homologação de fornecedores).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-09 23:33:39', '2026-01-09 23:33:39'),
(13, 'professor.produtos-acabados.index', 'GESTÃO DE PRODUTOS (Engenharia de Produto)', '<h3>🧸 Módulo de Produtos Acabados: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA Gestão de Produtos Acabados é o setor de <b>Engenharia de Produto</b> da fábrica. Aqui você define o portfólio de vendas da empresa. Diferente das matérias-primas, o Produto Acabado é o resultado final da linha de produção que será entregue ao cliente. Cada registro nesta tela define o preço de mercado, o tempo necessário para fabricação e, posteriormente, a sua \"receita\" (BOM) para o cálculo de materiais.\n\n<b>🟣 Card: Cadastrar Novo Produto (Registro de Engenharia)</b>\n\nNesta área, você insere as especificações comerciais e técnicas do item final:\n• <b>Empresa Detentora do Produto:</b>\n<b>Modelo Global:</b> O produto fica disponível para todas as turmas cadastradas.\n<b>Empresa Específica:</b> O produto pertence apenas a uma unidade, permitindo criar cenários de exclusividade de mercado.\n• <b>SKU (Código Interno):</b> Código identificador único do produto pronto (Ex: PRD-SKATE-01).\n• <b>Preço de Venda (R$):</b> Valor nominal que será cobrado do cliente. Este valor impacta diretamente no faturamento bruto do BI.\n• <b>Tempo de Produção (Dias):</b> Define o <b>Lead Time</b> fabril. É este dado que o sistema usa para alertar o PCP sobre a viabilidade das datas de entrega.\n\n<b>🟡 Card: Produtos Cadastrados (Gestão do Catálogo)</b>\n\nTabela central para monitoramento e manutenção dos itens de venda:\n• <b>Filtros de Visibilidade:</b> O Professor pode visualizar o catálogo de todas as empresas simultaneamente ou isolar uma unidade específica para auditoria.\n• <b>Manutenção de Dados:</b>\n<b>Editar:</b> Abre a tela detalhada onde, além dos dados básicos, é possível configurar a <b>Estrutura do Produto</b> (quais matérias-primas e quantidades compõem este item).\n<b>Excluir:</b> Remove o produto do catálogo ativo através do sistema de <b>Soft Deletes</b>, garantindo que pedidos antigos não percam a referência histórica.\n\n<b>🧠 Dicas do Mestre (Estratégia de Engenharia)</b>\n\n<b>Equilíbrio de Lead Time:</b> Ao definir o \"Tempo de Produção\", seja realista. Tempos muito curtos facilitam as vendas, mas podem gerar atrasos constantes se a logística de compras não for rápida o suficiente.\n<b>Margem de Contribuição:</b> O preço de venda deve cobrir o custo de todos os insumos somados. Após cadastrar o produto, não esqueça de entrar em \"Editar\" para vincular as matérias-primas e conferir o custo total.\n<b>Produtos Sazonais:</b> O Professor pode criar produtos específicos para uma turma durante uma crise, simulando demandas urgentes de mercado (ex: Kits de Emergência).\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Engenharia / Gerência</b> (Definição de mercado).\n• <b>Você envia dados para:</b> <b>Vendas</b> (Catálogo de Pedidos) e <b>PCP</b> (Necessidade de fabricação e explosão de materiais).\n\nManual da Fábrica Digital - Documentação Técnica de Engenharia', '2026-01-09 23:37:47', '2026-01-09 23:37:47'),
(14, 'professor.clientes.index', 'GESTÃO DE CLIENTES (CRM - Carteira de Parceiros)', '<h3>🤝 Módulo de Clientes: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA Gestão de Clientes atua como o banco de dados de <b>CRM (Customer Relationship Management)</b> da fábrica. Aqui são registrados os parceiros comerciais que comprarão os produtos da sua empresa. Um cadastro preciso é vital não apenas para a equipe de Vendas, mas também para a Expedição, pois o endereço e os dados fiscais (CNPJ/CPF) aqui inseridos serão utilizados automaticamente na emissão das Notas Fiscais no final do processo produtivo.\n\n<b>🟣 Card: Cadastrar Novo Cliente (Registro Comercial)</b>\n\nÁrea destinada à inserção de novos parceiros na base de dados:\n• <b>Pertence à Empresa:</b> Define a visibilidade do parceiro comercial.\n<b>Modelo Global:</b> O cliente fica disponível para todas as turmas da simulação.\n<b>Empresa Específica:</b> O cliente é exclusivo de uma fábrica (ex: Alpha), permitindo simular carteiras de clientes regionais ou nichos de mercado privados.\n• <b>Nome / Razão Social:</b> Nome oficial da entidade ou pessoa física.\n• <b>Dados de Contato:</b> Telefone e identificação fiscal (CNPJ ou CPF).\n• <b>Bloco de Localização:</b> Endereço completo (CEP, Rua, Número, Bairro, Cidade e UF). <b>Atenção:</b> Estes dados são obrigatórios para simular a logística de entrega.\n\n<b>🟡 Card: Clientes Cadastrados (Gestão da Carteira)</b>\n\nPainel de controle para monitoramento e auditoria da base de dados:\n• <b>Filtros de Empresa:</b> Permite ao Professor visualizar o mercado total do simulador ou isolar os clientes que pertencem a apenas uma equipe.\n• <b>Manutenção de Registros:</b>\n<b>Editar:</b> Permite atualizar dados de contato ou endereço se houver mudança na estratégia do jogo.\n<b>Excluir:</b> Remove o cliente da lista de seleção ativa. Graças ao sistema de <b>Soft Deletes</b>, se este cliente já possuir pedidos antigos, os dados históricos de faturamento no BI não serão afetados.\n\n<b>🧠 Dicas do Mestre (Estratégia de Mercado)</b>\n\n<b>Integridade dos Dados:</b> Instrua os alunos a preencherem o campo \"Cidade\" corretamente. Isso permite o uso de filtros geográficos no BI e facilita a análise de onde vem a maior demanda da fábrica.\n<b>Cenários de Exclusividade:</b> O Professor pode criar clientes com grandes demandas vinculados a apenas uma empresa para testar a capacidade produtiva daquela equipe específica sob pressão.\n<b>Cadastro de Novos Parceiros:</b> No início da simulação, é recomendável ter uma base de Clientes Globais sólida para que os alunos de Vendas possam iniciar as operações imediatamente.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Gerência / Professor</b> (Configuração inicial da carteira).\n• <b>Você envia dados para:</b> <b>Vendas</b> (Seleção no Pedido) e <b>Expedição</b> (Dados para emissão de Nota Fiscal).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-09 23:43:21', '2026-01-09 23:43:21'),
(15, 'professor.fornecedores.index', 'GESTÃO DE FORNECEDORES (SRM - Gestão de Suprimentos)', '<h3>🚛 Módulo de Fornecedores: Roteiro de Operação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA Gestão de Fornecedores é o pilar de <b>Suprimentos</b> da fábrica. Aqui você homologa os parceiros que irão abastecer sua linha de produção. Este cadastro é estratégico, pois define o <b>Preço Unitário</b> de compra e o <b>Prazo de Entrega</b>. No simulador, a escolha de um fornecedor errado pode elevar os custos de produção no BI ou causar paradas de máquina por demora na entrega da matéria-prima.\n\n<b>🟣 Card: Cadastrar Novo Fornecedor (Homologação)</b>\n\nÁrea para registro de novos canais de suprimento:\n• <b>Pertence à Empresa:</b>\n<b>Modelo Global:</b> O fornecedor atende a todas as fábricas do sistema.\n<b>Empresa Específica:</b> O fornecedor é exclusivo de uma turma, permitindo criar parcerias estratégicas privadas.\n• <b>Dados Cadastrais:</b> Nome/Razão Social, CNPJ e Contato.\n• <b>Especialidade e Condições:</b>\n<b>Material Fornecido:</b> Você pode vincular o fornecedor a uma matéria-prima específica. Isso filtra as opções de cotação para o aluno de Compras, simulando especialistas de mercado.\n<b>Preço Unitário (R$):</b> O valor que será cobrado por unidade. Impacta diretamente o gráfico de <b>Spend Analysis</b>.\n<b>Prazo de Entrega (Dias):</b> O tempo que o caminhão leva para chegar na doca. É o motor do cronômetro logístico do WMS.\n\n<b>🟡 Card: Fornecedores Homologados (Manutenção)</b>\n\nTabela de monitoramento dos parceiros ativos:\n• <b>Filtro de Contexto:</b> O Professor pode alternar entre ver todos os fornecedores ou apenas os de uma turma específica.\n• <b>Ações de Gestão:</b>\n<b>Editar:</b> Permite renegociar preços e prazos conforme o avanço da simulação.\n<b>Excluir:</b> Remove o fornecedor da lista de cotação. O sistema utiliza <b>Soft Deletes</b> para que o histórico de compras passadas (OCs) não seja apagado dos relatórios financeiros.\n\n<b>🧠 Dicas do Mestre (Estratégia de Compras)</b>\n\n<b>O Dilema do Comprador:</b> Ao cadastrar, decida entre um fornecedor <b>barato com entrega lenta</b> ou um fornecedor <b>caro com entrega imediata</b>. Isso cria desafios reais de planejamento para os alunos.\n<b>Fornecedores de Emergência:</b> O Professor pode criar fornecedores com prazo \"zero\" e preços altíssimos para simular compras de extrema urgência em caso de erros na produção.\n<b>Filtro Inteligente:</b> Se o professor selecionar uma empresa no topo, o sistema filtra automaticamente os materiais para que você vincule apenas insumos que aquela empresa utiliza.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Matérias-Primas</b> (Definição do que comprar).\n• <b>Você envia dados para:</b> <b>Compras</b> (Opções para cotação) e <b>BI / Torre de Controle</b> (Indicadores de custo e qualidade do fornecedor).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-09 23:47:23', '2026-01-09 23:47:23'),
(16, 'professor.global.alunos', 'GESTÃO GLOBAL DE ALUNOS (Banco de Talentos)', '<h3>👥 Banco de Talentos: Roteiro de Gestão de Usuários</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Banco de Talentos é o repositório central de todos os <b>Alunos (Operadores)</b> cadastrados no simulador. Diferente das outras telas, esta gestão é <b>Global</b>: um aluno matriculado aqui torna-se um \"recurso humano\" disponível para ser escalado em qualquer turma ou empresa criada pelo Professor. É a central de controle de acesso, onde se gerencia a entrada de novos participantes e a segurança das contas.\n\n<b>🟢 Card: Matricular Novo Aluno (Cadastro de Ingresso)</b>\n\nÁrea destinada a registrar novos estudantes no ecossistema da Fábrica Digital:\n• <b>Dados de Identificação:</b> Nome completo, E-mail (que servirá como login) e o curso/ano letivo para fins de organização pedagógica.\n• <b>Senha Inicial (3 Números):</b> Para facilitar o primeiro acesso, o sistema solicita apenas 3 dígitos finais. A senha padrão de nascimento será sempre o prefixo <b>Senai</b> seguido pelos 3 números escolhidos (Ex: Senai123).\n• <b>Validação:</b> O e-mail deve ser único no sistema para evitar duplicidade de perfis no banco de talentos.\n<b>📁 Card: Alunos no Sistema (Gestão de Acesso)</b>\nTabela de monitoramento e manutenção da base de usuários ativos:\n• <b>Status de Acesso (Ativar/Bloquear):</b> Ferramenta de moderação instantânea. Caso um aluno precise ser afastado ou a conta apresente comportamento indevido, o Professor pode <b>Bloquear</b> o usuário. Isso revoga o acesso dele a todas as empresas simuladas imediatamente.\n• <b>Reset de Senha:</b> Caso o aluno esqueça sua credencial, o botão <b>[RESET]</b> restaura a senha para o padrão fixo do sistema, permitindo a recuperação rápida da conta durante a aula.\n• <b>Contador de Registros:</b> Indica o volume total de \"talentos\" disponíveis para as próximas simulações.\n\n<b>🧠 Dicas do Mestre (Gestão de Pessoas)</b>\n\n<b>Segurança Primeiro:</b> O bloqueio de um usuário no Banco de Talentos é a \"Opção Nuclear\". Use-a para encerrar a participação de alunos que já concluíram o curso ou para pausar acessos de turmas inteiras por segurança.\n<b>Padronização de E-mail:</b> Recomende o uso do e-mail institucional ou um padrão único para a turma. Isso facilita a busca e a organização na hora de montar as equipes.\n<b>Controle de Turma:</b> Após matricular o aluno aqui, você ainda precisa ir em <b>[🏭 Turmas -> Equipe]</b> para dar a ele um \"emprego\" e um \"setor\" dentro de uma fábrica específica.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Secretaria / Professor</b> (Lista de novos ingressantes).\n• <b>Você envia dados para:</b> <b>Gestão de Equipes (Turmas)</b>, fornecendo a lista de profissionais aptos a operar a simulação industrial.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-09 23:51:24', '2026-01-09 23:51:24'),
(17, 'professor.turmas.index', 'MINHAS FÁBRICAS (Gestão de Turmas)', '<h3>🏭 Módulo de Turmas: Roteiro de Gestão de Empresas</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Minhas Fábricas é o centro de comando onde o <b>Professor (Game Master)</b> cria e gerencia os universos da simulação. Cada turma cadastrada aqui funciona como uma empresa isolada (Multi-tenant), com seu próprio estoque, carteira de clientes e relógio financeiro. É aqui que você define qual fábrica está ativa (\"Rodando\") e qual deve ser pausada para análise de resultados.\n\n<b>🟣 Botão: + Nova Turma (Abertura de Empresa)</b>\n\nClique aqui para inaugurar uma nova unidade produtiva no simulador. Você definirá o nome da empresa, o segmento de mercado e os dados corporativos (CNPJ e Endereço) que darão realismo à operação dos alunos.\n\n<b>🚀 Seção: Em Operação (Empresas Ativas)</b>\nExibe os cards das fábricas que estão atualmente em jogo. Cada card apresenta indicadores vitais:\n• <b>Status Operando:</b> Indica que o ambiente está visível para os alunos escalados.\n• <b>🌙 Arquivar:</b> Função para \"adormecer\" a fábrica. Use-a ao final de um semestre ou projeto. Os dados são preservados para o BI, mas o acesso dos alunos é bloqueado.\n• <b>Relógio do Jogo:</b> Exibe a data virtual daquela empresa específica. Lembre-se: cada fábrica pode estar em um \"tempo\" diferente, dependendo de como você avançou o cronograma.\n• <b>Colaboradores:</b> Contador em tempo real de quantos alunos foram vinculados à equipe desta fábrica.\n<b>🎛️ Botão Central: Painel de Controle</b>\nO acesso rápido para gerenciar a dinâmica do jogo:\n• Clique aqui para <b>Iniciar, Pausar ou Resetar</b> a simulação, além de ter acesso aos botões de <b>Avançar Tempo</b> (+1h, +1d) que movem a economia da empresa.\n<b>🛠️ Rodapé do Card (Ferramentas de Ajuste)</b>\n• <b>👥 Equipe:</b> Abre a tela de escalação onde você retira alunos do \"Banco de Talentos\" e define seus cargos (PCP, Vendas, Produção, etc.).\n• <b>📝 Editar:</b> Permite alterar os dados corporativos e a missão da empresa.\n• <b>🗑️ Excluir:</b> Ação destrutiva protegida por <b>Senha Mestra</b>. Realiza a limpeza profunda (Force Delete) de todos os rastros da empresa no sistema.\n<b>🧠 Dicas do Mestre (Gestão de Ambientes)</b>\n<b>Organização por Cores:</b> Utilize nomes de empresas distintos (Ex: Alpha, Beta, Delta) para facilitar sua identificação no Monitor Global.\n<b>O Poder do Arquivo:</b> Nunca exclua uma turma se quiser apresentar os gráficos de evolução em uma aula futura. Use sempre a função <b>[Arquivar]</b> para manter o histórico de aprendizado vivo.\n<b>Sincronia do Relógio:</b> Certifique-se de que o \"Relógio do Jogo\" está pausado antes de iniciar uma explicação teórica, para que os prazos de entrega dos alunos não vençam enquanto você fala.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Banco de Talentos</b> (Lista de alunos disponíveis).\n• <b>Você envia dados para:</b> <b>Todos os Módulos</b>, pois o turma_id é a âncora que isola e permite o funcionamento de toda a simulação.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:00:38', '2026-01-10 00:01:12');
INSERT INTO `sistema_ajuda` (`id`, `rota`, `titulo`, `conteudo`, `created_at`, `updated_at`) VALUES
(18, 'professor.turmas.edit', 'EDITAR PERFIL DA EMPRESA (Configuração da Turma)', '<h3>📝 Editar Perfil da Empresa: Roteiro de Configuração</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Edição de Perfil é onde o <b>Professor (Game Master)</b> personifica a simulação. Aqui, uma simples turma escolar é transformada em uma organização industrial completa. As informações inseridas nesta página são propagadas para todo o sistema, afetando desde o cabeçalho do portal do aluno até a emissão de documentos fiscais complexos (DANFE). É o centro de definição da identidade corporativa e estratégica da turma.\n\n<b>🆔 Seção 1: Identificação da Empresa</b>\n\nCampos destinados à nomenclatura e nicho de mercado:\n• <b>Nome da Turma / Classe:</b> Nome administrativo usado pelo professor para organizar suas turmas no painel geral.\n• <b>Nome Fantasia (Simulação):</b> O nome \"público\" que os alunos visualizarão em suas estações de trabalho e no monitor de Gestão à Vista.\n• <b>Setor e Segmento:</b> Define a especialização da fábrica (Ex: Setor Automobilístico / Segmento de Peças), conferindo contexto às atividades comerciais e produtivas.\n\n<b>📄 Seção 2: Dados Jurídicos e Contato</b>\n\nInformações para simulação de processos formais e cultura organizacional:\n• <b>CNPJ e Telefone:</b> Dados que conferem realismo às transações de compra e venda entre a fábrica e seus fornecedores/clientes.\n• <b>Resumo da Empresa / Missão:</b> O campo estratégico mais importante. Aqui o professor define o <b>\"DNA\"</b> da empresa. Uma missão bem escrita motiva os alunos e define os objetivos da gestão (Ex: \"Ser a empresa mais eficiente em entregas de alta qualidade\").\n\n<b>📍 Seção 3: Localização da Sede</b>\n\nDados geográficos da unidade produtiva:\n• <b>Endereço Completo:</b> Rua, Número, Bairro, Cidade e UF. Estes campos são exportados automaticamente para o módulo de <b>Expedição</b> para compor os dados do emitente nas Notas Fiscais. Uma localização correta é essencial para a imersão na logística de transporte simulada.\n\n<b>🧠 Dicas do Mestre (Configuração Estratégica)</b>\n\n<b>Imersão Profissional:</b> Ao cadastrar dados corporativos realistas, o professor aumenta o engajamento dos alunos, fazendo-os sentir que operam uma fábrica legítima no mercado.\n<b>Mudança de Rota:</b> Se a simulação estiver muito fácil, o professor pode alterar a \"Missão\" da empresa no meio do jogo para exigir novos resultados (Ex: Alterar o foco de \"Volume de Vendas\" para \"Redução de Refugo\").\n<b>Validação Fiscal:</b> Certifique-se de preencher a <b>UF (Estado)</b> corretamente, pois este dado é utilizado no BI para filtros de desempenho regional.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Decisão Pedagógica do Professor</b>.\n• <b>Você envia dados para:</b> <b>Todos os Módulos do Aluno</b> (Identidade visual no topo do site) e <b>Expedição</b> (Dados fiscais para faturamento).\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:05:29', '2026-01-10 00:05:54'),
(19, 'profile.edit', 'PERFIL DO USUÁRIO (Segurança e Credenciais)', '<h3>👤 Perfil do Usuário: Roteiro de Segurança</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Perfil é o espaço privativo de cada participante, seja ele um <b>Aluno (Operador)</b> ou o <b>Professor (Game Master)</b>. Aqui são gerenciadas as credenciais de acesso e a segurança da conta. Manter esses dados protegidos é fundamental, pois o acesso ao sistema permite o controle total sobre as operações financeiras e produtivas da fábrica.\n\n<b>🆔 Card: Identificação do Usuário</b>\n\nExibe os dados básicos de reconhecimento no sistema:\n• <b>Nome e E-mail:</b> Identificam quem é o responsável pelas ações registradas no banco de talentos e nos logs de operação.\n• <b>Nível de Acesso (Badge):</b> Indica se o usuário possui permissões de <b>Game Master</b> (acesso total às ferramentas de monitoramento e Caos) ou de <b>Aluno</b> (acesso restrito ao seu setor de trabalho).\n\n<b>🔒 Card: Atualizar Senha (Segurança da Conta)</b>\n\nÁrea destinada à manutenção da integridade do acesso:\n• <b>Senha Atual:</b> Para qualquer alteração, o sistema exige a validação da senha vigente, garantindo que ninguém altere suas credenciais em caso de esquecimento da sessão aberta.\n• <b>Nova Senha:</b> Escolha uma combinação segura. Lembre-se que em funções estratégicas (como PCP e Compras), um acesso indevido pode comprometer o resultado financeiro de toda a equipe.\n\n<b>🧠 Dicas do Mestre (Gestão de Acesso)</b>\n\n<b>Primeiro Acesso:</b> Recomenda-se que o aluno altere sua senha inicial (gerada com os 3 números do RG) logo no primeiro dia de simulação para evitar que colegas acessem seu setor indevidamente.\n<b>Alteração de Dados Sensíveis:</b> Caso necessite alterar o nome de exibição ou o e-mail cadastrado, note que, por segurança, essas funções são restritas ao Administrador do sistema.\n<b>Encerramento de Sessão:</b> Ao final da aula ou do turno de jogo, utilize sempre a função <b>[SAIR]</b> no menu superior para evitar que sua conta permaneça logada em computadores públicos do laboratório.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Sistema de Autenticação</b>.\n• <b>Você envia dados para:</b> <b>Logs de Operação</b>. Cada venda salva, cada material recebido e cada refugo apontado levará a assinatura do usuário logado neste perfil para fins de avaliação e auditoria.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:09:09', '2026-01-10 00:09:09'),
(20, 'professor.dashboard', 'PAINEL DO PROFESSOR (Central de Comando Game Master)', '<h3>🕹️ Painel do Professor: Roteiro de Gestão Master</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Painel de Controle é a \"Torre de Controle\" absoluta do simulador. É por aqui que o Professor (Game Master) supervisiona todas as instâncias das fábricas, controla o fluxo do tempo virtual e decide as regras de autonomia dos alunos. Esta tela oferece uma visão panorâmica da saúde de todas as turmas, permitindo intervenções rápidas para manter o equilíbrio pedagógico da simulação.\n\n<b>📊 Seção: Indicadores de Alto Nível (Estatísticas)</b>\nNo topo da tela, três cards principais resumem o estado global do sistema:\n• <b>Banco de Talentos:</b> Mostra o número total de alunos matriculados e aptos a serem escalados para as equipes.\n• <b>Turmas Criadas:</b> Indica quantas fábricas (empresas) foram fundadas sob sua gerência.\n• <b>Simulações Rodando:</b> Um indicador crítico que mostra quantas fábricas estão com o \"motor ligado\" (Jogo Ativo) no momento.\n\n<b>🎮 Seção: Centro de Comando (Fábricas em Tempo Real)</b>\n\nCada linha horizontal representa uma empresa independente. Aqui você opera o controle fino:\n• <b>Monitoramento por Setor:</b> Os ícones no centro do card (💰, 📊, 🛒, 📦, 🏭, 🎁, 🚚) permitem que você \"espione\" o que está acontecendo em cada departamento daquela turma sem precisar deslogar.\n\n• <b>Gestão à Vista (📺):</b> Botão de acesso rápido ao monitor Andon da turma para visualização do fluxo de pedidos.\n\n• <b>Motor de Tempo (Botões Verdes/Amarelos):</b>\n\n<b>Iniciar/Pausar:</b> Congela ou libera as ações de todos os alunos daquela turma.\n<b>Avançar Tempo (+1m, +30m, +1h, +1d):</b> Move o relógio da simulação para simular a passagem de dias e processar prazos de entrega e compras.\n\n• <b>Módulo Caos (⚡):</b> Link direto para injetar crises (quebra de máquinas e recusas) na empresa selecionada.\n\n<b>📋 Card: Regras Globais (Configuração de Autonomia)</b>\n\nEste painel define o nível de liberdade que os alunos terão durante a aula:\n• <b>Permissões de Cadastro:</b> Você pode habilitar ou desabilitar se os alunos podem cadastrar novos Clientes, Fornecedores ou Matérias-Primas.\n• <b>Estratégia:</b> Desative estas opções se quiser que os alunos foquem apenas na Operação (usando dados pré-cadastrados por você) ou ative-as se quiser testar a capacidade de Planejamento e Engenharia da equipe.\n\n<b>⚡ Card: Acesso Rápido (Atalhos de Gestão)</b>\nLinks diretos para as tabelas mestras do banco de dados:\n• Permite acesso imediato aos cadastros de Matérias-Primas, Produtos Acabados, Clientes e Fornecedores Globais, além da lista de Gestão de Pedidos de Venda de todas as turmas.\n\n<b>🧠 Dicas do Mestre (Comando da Simulação)</b>\n\n<b>Controle do Relógio:</b> O tempo só passa se você clicar nos botões de avanço. Utilize isso para criar \"rodadas\" de decisão (Ex: \"Vocês têm 10 minutos reais para planejar 2 dias virtuais\").\n<b>Modo Espionagem:</b> Use os botões de monitoramento de setor para identificar qual aluno está com dificuldade antes mesmo dele pedir ajuda.\n<b>Normalização:</b> Se a simulação sair do controle, utilize o botão <b>Pausar</b>. Isso impedirá que os pedidos atrasem enquanto você reorganiza a turma.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Todas as Operações dos Alunos</b> (Vendas, Compras, Produção).\n• <b>Você envia dados para:</b> <b>Todo o Ecossistema</b>, através do comando de Tempo, das Regras de Negócio e das Crises do Caos.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:14:27', '2026-01-10 00:14:27'),
(21, 'professor.monitoramento.index', 'CENTRO DE ESPIONAGEM (Monitoramento de Unidade)', '<h3>👁️ 🕵️ Centro de Espionagem: Roteiro de Monitoramento (God View)</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Centro de Espionagem é o painel de supervisão dedicada de uma única empresa (Turma). Diferente do painel geral, aqui o <b>Game Master</b> mergulha nos dados específicos daquela fábrica. É a ferramenta perfeita para auditorias pontuais, verificação de gargalos e para \"entrar na mente\" da equipe, acessando as mesmas telas que os alunos utilizam, mas com visão privilegiada.\n\n<b>🟣 Card: Torre de Controle (BI)</b>\n\nA ferramenta analítica mais poderosa do sistema:\n• <b>Inteligência de Dados:</b> Ao clicar aqui, você acessa dashboards financeiros, gráficos de eficiência (OEE) e indicadores de logística.\n• <b>Diagnóstico Rápido:</b> Utilize este acesso para verificar se a empresa está dando lucro ou prejuízo antes de aplicar uma intervenção de Caos.\n\n<b>🟡 Card: Monitor (Gestão à Vista)</b>\n\nO acesso ao painel Andon em tempo real:\n• <b>Rastreabilidade:</b> Veja exatamente onde cada pedido está parado (Vendas, PCP, Compras, etc.).\n• <b>Status Visual:</b> Ideal para projetar na sala de aula e mostrar aos alunos o fluxo de produção acontecendo (ou travando) ao vivo.\n\n<b>⚪ Cards: Acesso Setorial (Auditoria de Processos)</b>\n\nEstes botões (Vendas, PCP, Compras, WMS, Produção, Embalagem, Expedição) funcionam como \"portais\":\n• <b>Espionagem:</b> Ao clicar em um setor, você visualiza as tabelas e operações exatamente como o aluno vê.\n• <b>Verificação de Fraudes:</b> Use para conferir se os alunos estão apontando refugo corretamente na Produção ou se estão acumulando materiais sem dar entrada no WMS.\n\n<b>🧠 Dicas do Mestre (Supervisão Ativa)</b>\n\n<b>Investigação Cruzada:</b> Se o BI mostra prejuízo, use os botões dos setores para descobrir a causa raiz. Geralmente o problema está em <b>Compras</b> (pagando caro em urgências) ou <b>Produção</b> (gerando muito refugo).\n<b>Feedback em Tempo Real:</b> Mantenha esta tela aberta durante a aula. Se notar que o setor de \"Expedição\" está com muitos pedidos acumulados, alerte a equipe imediatamente.\n<b>Navegação Rápida:</b> Use o botão <b>[⬅ Voltar ao Painel Geral]</b> no topo para trocar rapidamente de empresa e comparar o desempenho entre os grupos concorrentes.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Todos os Módulos Operacionais</b> daquela turma específica.\n• <b>Você envia dados para:</b> <b>Avaliação do Professor</b>. As informações coletadas aqui servem de base para a nota técnica e comportamental da equipe.\n\nManual da Fábrica Digital - Documentação Técnica de Gestão', '2026-01-10 00:18:55', '2026-01-11 04:10:19'),
(22, 'professor.caos.index', 'PAINEL DO CAOS (Gestão de Crises e Contingência)', '<h3>⚡ Painel do Caos: Roteiro de Gestão de Crises</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Painel do Caos é a ferramenta de <b>intervenção direta</b> do Professor (Game Master). Diferente dos outros módulos que buscam a eficiência, este painel serve para testar a resiliência, a comunicação e a capacidade de resolução de problemas dos alunos. Através dele, você injeta imprevistos reais do mundo industrial, forçando as equipes a saírem do \"caminho feliz\" e lidarem com atrasos, quebras e falhas de qualidade.\n\n<b>🟡 Card: Plantão de Notícias (Pop-up para Alunos)</b>\n\nEste é o canal oficial de comunicação de crise:\n• <b>Publicar Notícia:</b> O texto digitado aqui aparece instantaneamente no topo da tela de todos os alunos da turma. Use para dar contexto ao caos (Ex: \"Greve geral dos portos iniciada\" ou \"Auditoria surpresa no almoxarifado\").\n\n<b>🔴 Card: Bloqueios Globais (Setores Parados)</b>\n\nAtua paralisando departamentos inteiros por um período determinado de dias virtuais:\n• <b>Almoxarifado / Expedição / Faturamento:</b> Ao clicar em <b>[TRAVAR]</b>, o setor escolhido fica impossibilitado de realizar qualquer operação. Os botões de ação dos alunos desaparecem, simulando uma greve ou queda de sistema de TI.\n\n<b>🟠 Card: Quebrar Máquina (Manutenção Corretiva)</b>\n\nAtua diretamente em uma Ordem de Produção (OP) específica:\n• <b>Sabotagem Técnica:</b> Escolha uma OP que esteja \"Em Produção\" e defina quantos dias ela ficará parada. A máquina será desligada e o ícone de manutenção (🔥) aparecerá no Monitor, obrigando o PCP a reprogramar a fábrica.\n\n<b>🟣 Card: Atrasar Entrega (Logística de Suprimentos)</b>\n\nSimula falhas na cadeia de suprimentos:\n• <b> turtles Atraso de Fornecedor:</b> Selecione uma Ordem de Compra (OC) que esteja a caminho e adicione dias extras ao prazo de entrega. Isso testa se o PCP e o Almoxarifado possuem estoque de segurança para aguentar a demora.\n\n<b>🟫 Cards: Sabotar Carga (WMS) e Sabotar Produção</b>\n\nAs ferramentas mais avançadas de <b>Inconformidade Programada</b>:\n• <b>Sabotar Carga:</b> Você escolhe uma carga e define um defeito (Ex: Embalagem Violada). O aluno de WMS será bloqueado de receber o material e obrigado a processar a recusa.\n• <b>Sabotar Produção:</b> Você escolhe uma OP e define uma quantidade de peças que devem ser perdidas. O aluno será obrigado a apontar refugo, gerando um rastro financeiro de prejuízo no BI.\n\n<b>🟢 Botão: Restaurar a Paz (Normalizar Tudo)</b>\n\nO \"botão de emergência\" do Professor:\n• <b>Reset de Crises:</b> Ao clicar aqui, todas as máquinas são consertadas e todos os bloqueios de setores são removidos imediatamente. Utilize para iniciar um novo ciclo de jogo ou limpar o ambiente após um teste de estresse.\n\n<b>🧠 Dicas do Mestre (Estratégia de Caos)</b>\n\n<b>Dosagem Pedagógica:</b> Não injete todas as crises ao mesmo tempo. O objetivo é ensinar o aluno a priorizar problemas, não travar a simulação por completo.\n<b>Rastreabilidade do Erro:</b> Após sabotar uma carga ou produção, vá ao <b>Monitor (Gestão à Vista)</b> para verificar se os alunos identificaram a causa do atraso e se o setor de Compras já providenciou a reposição.\n<b>Impacto Financeiro:</b> Lembre os alunos de consultarem o <b>Custo da Ineficiência</b> no BI. Eles devem sentir que cada erro técnico (sabotado ou não) custa dinheiro real para a empresa.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Monitoramento Global</b> (Para saber onde atacar).\n• <b>Você envia dados para:</b> <b>Todos os Setores</b>, alterando o status de máquinas, materiais, prazos e permissões de acesso.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:23:01', '2026-01-10 00:23:01'),
(23, 'professor.turmas.equipe', 'ESCALAÇÃO DA EQUIPE (Montagem de Equipes)', '<h3>📋 Módulo de Escalação: Roteiro de Montagem de Equipes</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Escalação é o departamento de <b>Recursos Humanos</b> do simulador. Aqui, o Professor (Game Master) recruta os estudantes do Banco de Talentos Global e os distribui estrategicamente pelos departamentos da fábrica selecionada. Sem uma equipe escalada e com cargos definidos, a empresa permanece inoperante, pois os alunos não conseguem acessar as ferramentas de trabalho dos setores.\n\n<b>🟣 Card: Alunos Disponíveis (Seleção de Talentos)</b>\n\nNeste painel, você visualiza todos os alunos cadastrados no sistema que ainda não fazem parte desta equipe específica:\n• <b>Lista de Profissionais:</b> Exibe o nome e o curso original do aluno.\n• <b>Botão [ESCALAR ➔]:</b> Ao clicar, você realiza a \"contratação\" imediata do aluno para esta fábrica. Ele sairá da lista de disponíveis e entrará na lista de Equipe Ativa.\n\n<b>🟡 Card: Equipe Ativa (Postos de Trabalho)</b>\n\nEste é o quadro de funcionários da sua empresa. Cada aluno escalado aparece em um card individual de controle:\n• <b>Seletor de Setor Alocado:</b> Esta é a configuração mais importante. Você deve clicar no menu suspenso <b>-- DEFINIR CARGO --</b> e escolher em qual departamento o aluno vai operar (Vendas, PCP, Compras, WMS, Produção, Embalagem ou Expedição).\n• <b>Acesso Direto:</b> Assim que você define o cargo, o sistema libera o \"GPS\" do Aluno, enviando-o automaticamente para a tela correta na próxima vez que ele logar.\n• <b>Remoção (X Vermelho):</b> Permite desligar um aluno da equipe. O aluno volta para o Banco de Talentos e pode ser escalado em outra fábrica se necessário.\n\n<b>🧠 Dicas do Mestre (Estratégia de Liderança)</b>\n\n<b>Equilíbrio de Carga:</b> Uma fábrica eficiente precisa de pelo menos um aluno em cada setor crítico (PCP, WMS e Produção). Se você deixar o setor de Compras vazio, a Produção acabará parando por falta de material.\n<b>Rotação de Cargos:</b> Você pode alterar o setor de um aluno em tempo real durante a aula. Basta mudar o cargo no menu suspenso. Isso permite simular a rotatividade de funções e o aprendizado multifuncional.\n<b>Contador de Operadores:</b> Monitore o número de operadores no topo do card amarelo para garantir que a equipe não ultrapasse o limite físico planejado para a dinâmica.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Banco de Talentos</b> (Candidatos disponíveis).\n• <b>Você envia dados para:</b> <b>Dashboards dos Alunos</b> (Permissões de acesso aos setores) e <b>Monitor de Gestão à Vista</b> (Identificação de quem está operando cada processo).\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:27:20', '2026-01-10 00:27:20'),
(24, 'professor.pedidos-venda.index', 'GESTÃO DE PEDIDOS (Visão Game Master)', '<h3>💰 Gestão de Pedidos de Venda: Roteiro de Supervisão</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nDiferente da tela do aluno, a Gestão de Pedidos para o Professor atua como uma <b>Torre de Comando Comercial</b>. Aqui você supervisiona o faturamento de todas as empresas simultaneamente. O Professor tem o \"Poder de Mercado\": você pode injetar pedidos manualmente para testar a agilidade de uma turma específica ou auditar vendas suspeitas. É a ferramenta essencial para equilibrar a oferta e a demanda dentro do simulador.\n\n<b>🟣 Barra de Contexto: Modo Focado</b>\n\nSempre que você acessa os pedidos vindo de uma turma específica no Dashboard, o sistema ativa o <b>Modo Focado</b>:\n• <b>Isolamento Visual:</b> A barra azul escura no topo confirma qual empresa você está auditando.\n• <b>Navegação:</b> Use o botão <b>[Ver Todas as Turmas]</b> para sair do filtro e visualizar o faturamento global de todos os seus alunos de uma só vez.\n\n<b>🔵 Card: Novo Pedido (Injeção de Demanda)</b>\n\nÁrea onde o Professor cria ordens de venda para os alunos processarem:\n• <b>1. Empresa:</b> Selecione qual fábrica receberá o pedido. O sistema travará este campo automaticamente se você estiver no Modo Focado.\n• <b>2. Cliente:</b> Escolha um parceiro da carteira.\n• <b>3. Data Atual (Simulação):</b> O sistema exibe o relógio exato da empresa escolhida para garantir que o pedido não nasça com data retroativa.\n• <b>4. Itens do Pedido:</b> O seletor de produtos é <b>Inteligente</b>; ele filtrará e mostrará apenas os produtos que a empresa selecionada tem autorização para fabricar (ou modelos globais).\n\n<b>⚪ Card: Filtrar Pedidos (Ferramenta de Auditoria)</b>\n\nComo o volume de vendas pode ser massivo, utilize os filtros para encontrar gargalos:\n• <b>Busca Multicritério:</b> Filtre por Status (ex: Pedidos parados em \"Novo\"), por Produto (quais fábricas estão fazendo mais Skates?) ou por Localização do cliente.\n• <b>Ticket Médio:</b> Analise quais turmas estão focando em pedidos de alto valor e quais estão focando em volume de vendas.\n\n<b>🟡 Card: Carteira de Pedidos (Monitoramento Global)</b>\n\nA listagem centralizada de todos os compromissos comerciais:\n• <b>Status Operacional:</b> Acompanhe em tempo real se o pedido está em fase de planejamento (Novo), fabricação (Em Produção) ou se já gerou lucro (Faturado).\n• <b>Ações Master:</b>\n<b>Lupa (Ver):</b> Detalha os itens e a rastreabilidade.\n<b>Lápis (Editar):</b> Permite corrigir datas de entrega se você quiser dar mais tempo ou pressionar a equipe.\n<b>X (Cancelar):</b> Ação protegida por <b>Senha Mestra</b>. Cancela a venda e interrompe o fluxo no PCP e na Produção.\n\n<b>🧠 Dicas do Mestre (Gestão de Fluxo)</b>\n\n<b>Injeção de Crise:</b> Para testar o PCP, crie um pedido gigante com uma data de entrega curtíssima. Observe no Monitor como a equipe se organiza para priorizar essa ordem.\n<b>Auditoria de Preços:</b> Verifique se o valor total dos pedidos condiz com a estratégia financeira da turma.\n<b>Limpeza de Banco:</b> Utilize o cancelamento de pedidos antigos para limpar o Monitor de turmas que já encerraram o ciclo de aprendizagem.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Clientes e Produtos Acabados</b> (Para compor a venda).\n• <b>Você envia dados para:</b> <b>PCP dos Alunos</b> (Que visualizarão o pedido como uma nova demanda no dashboard deles).\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:31:07', '2026-01-10 00:31:07'),
(25, 'professor.pedidos-venda.show', 'DETALHES DO PEDIDO (Visão de Auditoria)', '<h3>🔍 Detalhes da Venda: Roteiro de Auditoria</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Detalhes do Pedido é a ferramenta de <b>investigação profunda</b> do Professor (Game Master). Enquanto as outras telas mostram listas gerais, esta página permite dissecar uma única transação comercial. É aqui que você valida se o aluno de Vendas configurou o contrato corretamente antes que ele avance para os estágios irreversíveis de produção.\n\n<b>⬜ Card 1: Cliente / Parceiro</b>\n\nIdentificação da ponta compradora:\n• <b>Dados Cadastrais:</b> Verifique se o Nome e o CNPJ/CPF conferem.\n• <b>Localização:</b> A cidade e o estado (UF) definem a lógica logística. Se o cliente for de muito longe, o prazo de entrega deveria ser maior.\n\n<b>⬜ Card 2: Cronograma (Prazos)</b>\n\nOnde se mede a eficiência do PCP contra a promessa de Vendas:\n• <b>Emissão:</b> Data de entrada do pedido no sistema (Data do Jogo).\n• <b>Entrega Solicitada:</b> A meta (\"Deadline\"). Se a data atual do simulador já passou desta data, o pedido está em atraso.\n\n<b>⬜ Card 3: Total e Status</b>\n\nResumo financeiro e operacional:\n• <b>Valor (R$):</b> O montante financeiro que entrará no caixa após o faturamento.\n• <b>Status Atual:</b> A etiqueta preta indica a fase (Novo, Em Produção, Concluído ou Faturado).\n\n<b>📦 Tabela: Itens Inclusos no Pedido</b>\n\nA composição técnica da venda:\n• <b>SKU e Produto:</b> O que deve ser fabricado.\n• <b>Qtd (Quantidade):</b> O número que multiplica a necessidade de materiais no MRP.\n• <b>Subtotal:</b> Permite conferir se não houve erro de precificação unitária.\n\n<b>🧠 Dicas do Mestre (Perícia)</b>\n\n<b>Botão Imprimir:</b> Utilize o botão <b>[🖨️ IMPRIMIR]</b> no topo do card roxo para gerar um PDF ou folha física. Isso é excelente para simular \"Ordens de Serviço\" em papel na sala de aula.\n<b>Viabilidade:</b> Compare a data de \"Emissão\" com a \"Entrega\". Prazos menores que 2 dias geralmente exigem estoque pronto ou compras urgentes.\n<b>Auditoria:</b> Se o valor total parecer irreal, use o botão <b>[⬅ Voltar]</b> e vá para a edição corrigir.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem:</b> <b>Vendas</b> (Criação do contrato).\n• <b>Destino:</b> <b>PCP</b> (Planejamento) e <b>Expedição</b> (Base para a Nota Fiscal).\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:35:12', '2026-01-11 05:23:38'),
(26, 'professor.pedidos-venda.edit', 'EDIÇÃO DE PEDIDOS (Ajuste de Demanda)', '<h3>📝 Editar Pedido de Venda: Roteiro de Ajustes Master</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Edição de Pedidos é a ferramenta de <b>intervenção cirúrgica</b> do Professor (Game Master). Ela permite alterar as condições de um contrato de venda mesmo após ele ter sido gerado. Seja para corrigir um erro de digitação do aluno ou para simular uma renegociação de contrato em tempo real, esta tela garante flexibilidade total sobre a demanda que a fábrica precisa atender.\n\n<b>🟣 Card: Dados do Contrato (Edição de Cabeçalho)</b>\n\nNesta seção, você altera as condições globais da venda:\n• <b>Cliente e Empresa:</b> Permite transferir ou corrigir o vínculo da venda.\n• <b>Nova Data de Entrega:</b> Atua diretamente na pressão sobre o PCP e a Produção. Ao encurtar este prazo, você testa a capacidade da equipe de reagir a urgências.\n• <b>Botão [ATUALIZAR CABEÇALHO]:</b> Salva as mudanças feitas nos dados mestres antes de prosseguir para os itens.\n\n<b>📦 Card: Itens do Pedido (Gestão de Mix e Volume)</b>\n\nAqui você manipula o conteúdo físico da ordem de venda:\n• <b>Listagem Atual:</b> Exibe o SKU, quantidade e preço unitário negociado.\n• <b>Ações nos Itens:</b>\n<b>Editar:</b> Permite alterar a quantidade de um item já existente. O sistema recalcula o valor total do pedido automaticamente.\n<b>Remover:</b> Exclui um produto do pedido, reduzindo a carga de trabalho da fábrica.\n• <b>Adicionar Novo Item:</b> Permite inserir novos produtos no mesmo contrato. O seletor é inteligente e mostrará apenas os produtos autorizados para a empresa em questão.\n\n<b>🧠 Dicas do Mestre (Manipulação de Cenários)</b>\n\n<b>Simulação de Aditivos:</b> Use a função \"Adicionar Novo Item\" para simular um cliente que decidiu aumentar o pedido após o fechamento, testando se o PCP consegue encaixar a nova demanda no cronograma.\n<b>Gestão de Prazos:</b> Se a turma estiver operando com muita facilidade, \"puxe\" a data de entrega para um dia mais próximo. Isso forçará os alunos a utilizarem o Painel de Gestão à Vista para identificar prioridades.\n<b>Correção de Preços:</b> Caso o aluno tenha vendido um produto com preço errado, a edição permite restaurar a saúde financeira da empresa antes do faturamento final.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Vendas (Aluno)</b> ou <b>Cadastro de Produtos</b>.\n• <b>Você envia dados para:</b> <b>Monitor de Gestão à Vista</b> e <b>PCP</b>. Qualquer alteração aqui reflete instantaneamente na fila de trabalho dos alunos, que verão o status ou as quantidades mudarem em seus dashboards.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 00:39:56', '2026-01-11 05:15:29'),
(27, 'aluno.empresa.perfil', 'Perfil Corporativo (Identidade da Empresa)', '<h3>🏢 Perfil Corporativo: Roteiro de Visualização</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Perfil Corporativo é a <b>\"Certidão de Nascimento\"</b> da sua empresa. Nesta tela, todos os colaboradores podem consultar a identidade jurídica e estratégica da organização. Ela define o propósito da fábrica, sua localização física e sua posição no mercado. Ter uma missão clara ajuda a guiar as decisões de todos os departamentos em direção aos objetivos da gerência.\n\n<b>🟣 Cabeçalho: Registro de Atividade Industrial</b>\n\nA parte superior do card identifica os dados mestres da empresa:\n\n• <b>Nome da Unidade:</b> O nome fantasia da sua fábrica (Ex: BETA).\n• <b>Setor e Segmento:</b> Define em qual mercado a empresa atua. Caso apareça como \"Não Definido\", significa que a estratégia de nicho ainda não foi oficializada pelo Professor.\n\n<b>📄 Card: Resumo e Missão</b>\nEste campo descreve a <b>alma da empresa</b>.\n• <b>Propósito:</b> Aqui deve constar o que a empresa faz e quais são seus valores. É um campo fundamental para a imersão no jogo, transformando a turma em uma corporação real com objetivos de mercado definidos.\n\n<b>📍 Card: Dados Legais e Localização</b>\n\nInformações de contato e registro para fins de faturamento e logística:\n• <b>CNPJ e Contato:</b> Dados necessários para a formalização de compras e vendas.\n• <b>Endereço da Unidade:</b> A localização geográfica da fábrica. Esses dados são utilizados automaticamente pelo sistema para compor o cabeçalho das suas <b>Notas Fiscais (DANFE)</b> no setor de Expedição.\n\n<b>🧠 Dicas do Mestre (Identidade de Marca)</b>\n\n<b>Visualização Restrita:</b> Note que esta tela é de <b>Apenas Leitura</b> para os alunos. Somente o Professor (Game Master) possui as credenciais para alterar o nome, endereço ou CNPJ da organização.\n<b>Imersão:</b> Leia atentamente a \"Missão\" da sua empresa. Ela pode conter pistas sobre o nível de exigência de qualidade ou sobre a prioridade de atendimento que o Professor espera da sua equipe.\n<b>Documentação:</b> Verifique se o endereço está correto, pois ele aparecerá em todos os documentos impressos e digitais gerados pela sua operação logística.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Professor (Gerência)</b>, que configura a identidade da turma.\n• <b>Você envia dados para:</b> <b>Expedição e Vendas</b>, alimentando os dados de cabeçalho das Notas Fiscais e Pedidos.\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-10 01:12:56', '2026-01-10 01:12:56'),
(28, 'aluno.embalagem.dashboard', '6. SETOR DE EMBALAGEM (PACKING & CONSOLIDAÇÃO)', '🎁 Módulo de Embalagem: Roteiro de Operação\n\n\n1. Visão Geral do Setor\n\nO setor de Embalagem é o posto de controle final da qualidade física do produto. Sua função é receber os lotes concluídos na Produção e realizar a conferência rigorosa de cada componente antes de lacrar a embalagem definitiva. Este setor garante que o cliente receba exatamente o que comprou, sem peças faltando ou erros de montagem.\n\n🟢 Card: Estação de Embalagem (Controle de Lotes)\n\nCada produto que sai da linha de montagem aparece automaticamente na sua esteira de empacotamento:\n• Status de Produção: Verifique se a quantidade produzida atende à meta da Ordem de Produção (ex: 5/5). Se o lote estiver incompleto devido a refugo, o sistema bloqueará o lacre até que a reposição seja concluída.\n• Checklist de Materiais (Status WMS): Confirme se todos os insumos necessários (BOM) foram devidamente entregues pelo Almoxarifado. O sistema sinaliza com um \"✓\" os materiais disponíveis.\n• Conferência Física: Você deve marcar manualmente cada item da lista para validar que as peças estão fisicamente na mesa de embalagem.\n\n🟢 Botão: Lacrar Lote / Embalar\n\nEsta é a ação que oficializa a entrada do produto no estoque final:\n• Validação: O botão só será habilitado após todos os itens do checklist serem marcados e a produção estar 100% concluída.\n• Entrada no Estoque: Ao clicar em [Lacrar Lote], as unidades produzidas saem da \"Esteira\" e entram no saldo de Produtos Acabados da empresa, ficando disponíveis para a Expedição faturar.\n\n🧠 Dicas do Mestre (Estratégia de Qualidade)\n\nGargalo na Esteira: Se houver muitos lotes acumulados \"Dormindo\" na embalagem, a Expedição não terá o que vender, travando o faturamento da empresa. Mantenha o fluxo constante!\nLote Incompleto: Caso veja a mensagem \"Lote Incompleto (Refugo)\", saiba que a Produção ainda está aguardando material de reposição do WMS. Você não pode embalar \"meio produto\".\n\nMonitoramento: Use o [📺 MONITOR] para prever quais OPs estão em fase final de montagem e prepare suas embalagens e etiquetas com antecedência.\n\n🔗 Conexão entre Setores\n\n• Você recebe dados de: Produção (Lotes Concluídos) e WMS (Status de entrega de insumos).\n• Você envia dados para: Expedição (Saldo de estoque pronto para faturamento).\n\nManual da Fábrica Digital - Documentação Técnica de Embalagem', '2026-01-10 05:08:19', '2026-01-10 05:08:19'),
(29, 'aluno.materias-primas.index', 'CADASTRO DE MATÉRIAS- PRIMAS', '📦 Módulo de Matérias-Primas: Roteiro de Operação\n\n\n1. Visão Geral do Setor\n\nA gestão de Matérias-Primas é a fundação de toda a cadeia produtiva. Sem o cadastro correto dos insumos, o PCP não consegue planejar a receita dos produtos e o setor de Compras não consegue realizar cotações. Esta tela é uma ferramenta híbrida: enquanto o Aluno foca nos materiais de sua unidade, o Professor atua na padronização global e na supervisão de todos os estoques da simulação.\n\n🟣 Card: Cadastrar Novo Insumo (Registro de Entrada)\n\nAqui é definida a identidade técnica de cada componente que entrará na fábrica:\n• SKU (Código): Identificador único do material (Ex: MP-001). Use códigos lógicos para facilitar a busca no Almoxarifado.\n• Nome do Material: Descrição clara do item (Ex: Prancha de Madeira, Eixo de Aço).\n• Unidade: Define a métrica de controle (kg, un, lt, m). Lembre-se: o PCP usará esta unidade para calcular o consumo na produção.\n\n🟡 Card: Inventário de Matérias-Primas (Gestão de Dados)\n\nA tabela central de consulta e auditoria dos registros:\n• Filtro de Empresa: O Professor pode alternar entre \"Todas as Empresas\" para uma visão de administrador ou filtrar uma turma específica. O Aluno visualiza apenas o que é pertinente à sua operação.\n• Ações Técnicas:\nEditar: Permite corrigir nomes ou unidades.\nExcluir: Remove o material da lista ativa. O sistema utiliza Soft Deletes, preservando o histórico de compras e produções antigas no banco de dados.\n\n🧠 Dicas do Mestre (Estratégia de Engenharia)\nPadronização de SKU: Evite criar SKUs genéricos como \"001\". Prefira nomenclaturas que identifiquem a família do produto, como \"MET-01\" para metais, facilitando a organização visual no Mapa WMS.\nCuidado com a Unidade: Mudar a unidade de medida após o início do jogo pode causar erros de cálculo no MRP. Defina a métrica correta no momento do cadastro.\nVisão Global: Materiais globais economizam tempo de cadastro, mas materiais específicos permitem que o Professor crie cenários de escassez para testar a negociação entre os alunos.\n\n🔗 Conexão entre Setores\n• Você recebe dados de: Professor / Engenharia (Definição de insumos necessários).\n• Você envia dados para: PCP (Para compor a BOM/Receita) e Compras (Para homologação de fornecedores).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-10 05:10:50', '2026-01-10 05:32:48'),
(30, 'aluno.clientes.index', 'GESTÃO DE CLIENTES (CRM- CARTEIRA DE PARCEIROS)', '🤝 Módulo de Clientes: Roteiro de Operação\n\n\n1. Visão Geral do Setor\n\nA Gestão de Clientes atua como o banco de dados de CRM (Customer Relationship Management) da fábrica. Aqui são registrados os parceiros comerciais que comprarão os produtos da sua empresa. Um cadastro preciso é vital não apenas para a equipe de Vendas, mas também para a Expedição, pois o endereço e os dados fiscais (CNPJ/CPF) aqui inseridos serão utilizados automaticamente na emissão das Notas Fiscais no final do processo produtivo.\n\n🟣 Card: Cadastrar Novo Cliente (Registro Comercial)\n\nÁrea destinada à inserção de novos parceiros na base de dados:\n• Nome / Razão Social: Nome oficial da entidade ou pessoa física.\n• Dados de Contato: Telefone e identificação fiscal (CNPJ ou CPF).\n• Bloco de Localização: Endereço completo (CEP, Rua, Número, Bairro, Cidade e UF). Atenção: Estes dados são obrigatórios para simular a logística de entrega.\n\n🟡 Card: Clientes Cadastrados (Gestão da Carteira)\n\nPainel de controle para monitoramento e auditoria da base de dados:\n• Filtros de Empresa: Permite ao Professor visualizar o mercado total do simulador ou isolar os clientes que pertencem a apenas uma equipe.\n• Manutenção de Registros:\nEditar: Permite atualizar dados de contato ou endereço se houver mudança na estratégia do jogo.\nExcluir: Remove o cliente da lista de seleção ativa. Graças ao sistema de Soft Deletes, se este cliente já possuir pedidos antigos, os dados históricos de faturamento no BI não serão afetados.\n\n🧠 Dicas do Mestre (Estratégia de Mercado)\n\nIntegridade dos Dados: Instrua os alunos a preencherem o campo \"Cidade\" corretamente. Isso permite o uso de filtros geográficos no BI e facilita a análise de onde vem a maior demanda da fábrica.\nCenários de Exclusividade: O Professor pode criar clientes com grandes demandas vinculados a apenas uma empresa para testar a capacidade produtiva daquela equipe específica sob pressão.\nCadastro de Novos Parceiros: No início da simulação, é recomendável ter uma base de Clientes Globais sólida para que os alunos de Vendas possam iniciar as operações imediatamente.\n\n🔗 Conexão entre Setores\n\n• Você recebe dados de: Gerência / Professor (Configuração inicial da carteira).\n• Você envia dados para: Vendas (Seleção no Pedido) e Expedição (Dados para emissão de Nota Fiscal).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-10 05:13:14', '2026-01-10 05:36:00'),
(31, 'aluno.fornecedores.index', 'GESTÃO DE FORNECEDORES (SRM - GESTÃO DE SUPRIMENTOS)', '🚛 Módulo de Fornecedores: Roteiro de Operação\n\n\n1. Visão Geral do Setor\n\nA Gestão de Fornecedores é o pilar de Suprimentos da fábrica. Aqui você homologa os parceiros que irão abastecer sua linha de produção. Este cadastro é estratégico, pois define o Preço Unitário de compra e o Prazo de Entrega. No simulador, a escolha de um fornecedor errado pode elevar os custos de produção no BI ou causar paradas de máquina por demora na entrega da matéria-prima.\n\n🟣 Card: Cadastrar Novo Fornecedor (Homologação)\n\nÁrea para registro de novos canais de suprimento:\n• Dados Cadastrais: Nome/Razão Social, CNPJ e Contato.\n• Especialidade e Condições:\nMaterial Fornecido: Você pode vincular o fornecedor a uma matéria-prima específica. Isso filtra as opções de cotação para o aluno de Compras, simulando especialistas de mercado.\nPreço Unitário (R$): O valor que será cobrado por unidade. Impacta diretamente o gráfico de Spend Analysis.\nPrazo de Entrega (Dias): O tempo que o caminhão leva para chegar na doca. É o motor do cronômetro logístico do WMS.\n\n🟡 Card: Fornecedores Homologados (Manutenção)\n\nTabela de monitoramento dos parceiros ativos:\n• Filtro de Contexto: O Professor pode alternar entre ver todos os fornecedores ou apenas os de uma turma específica.\n• Ações de Gestão:\nEditar: Permite renegociar preços e prazos conforme o avanço da simulação.\nExcluir: Remove o fornecedor da lista de cotação. O sistema utiliza Soft Deletes para que o histórico de compras passadas (OCs) não seja apagado dos relatórios financeiros.\n\n🧠 Dicas do Mestre (Estratégia de Compras)\n\nO Dilema do Comprador: Ao cadastrar, decida entre um fornecedor barato com entrega lenta ou um fornecedor caro com entrega imediata. Isso cria desafios reais de planejamento para os alunos.\nFornecedores de Emergência: O Professor pode criar fornecedores com prazo \"zero\" e preços altíssimos para simular compras de extrema urgência em caso de erros na produção.\nFiltro Inteligente: Se o professor selecionar uma empresa no topo, o sistema filtra automaticamente os materiais para que você vincule apenas insumos que aquela empresa utiliza.\n\n🔗 Conexão entre Setores\n\n• Você recebe dados de: Matérias-Primas (Definição do que comprar).\n• Você envia dados para: Compras (Opções para cotação) e BI / Torre de Controle (Indicadores de custo e qualidade do fornecedor).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-10 05:15:49', '2026-01-10 05:36:43'),
(32, 'professor.materias-primas.edit', 'EDITAR MATÉRIA-PRIMA (Ajuste de Insumo)', '<h3>📝 Editar Matéria-Prima: Roteiro de Ajustes</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Edição de Insumo permite ao <b>Professor (Game Master)</b> corrigir ou atualizar as especificações técnicas de um material já cadastrado. Alterações feitas aqui refletem imediatamente em todo o sistema, atualizando o nome e a unidade de medida em ordens de compra pendentes, estoques do WMS e receitas de produção. É uma ferramenta de manutenção da base de dados.\n\n<b>🟣 Card: Ficha Técnica da Matéria-Prima</b>\n\nAqui você altera a identidade do material:\n• <b>SKU (Código Interno):</b> Identificador logístico (Ex: MP-001). Alterar o SKU ajuda a reorganizar o padrão de codificação da fábrica sem perder o histórico do item.\n• <b>Nome do Material:</b> Descrição que aparece para os alunos. Use para corrigir erros de digitação ou para mudar a natureza do insumo (Ex: mudar de \"Aço\" para \"Alumínio\" em um cenário de crise).\n• <b>Unidade de Medida:</b> A métrica de controle (kg, m, un). <b>Atenção:</b> Alterar a unidade de um material que já possui estoque pode causar confusão no PCP (Ex: mudar de \"Quilos\" para \"Toneladas\" sem ajustar o saldo).\n\n<b>🧠 Dicas do Mestre (Gestão de Dados)</b>\n\n<b>Impacto Imediato:</b> Lembre-se que ao mudar o nome de um material, todas as OPs e OCs em andamento passarão a exibir o novo nome instantaneamente.\n<b>Correção de Erros:</b> Se um aluno cadastrou um material com unidade errada (ex: \"Metros\" em vez de \"Rolos\"), use esta tela para corrigir antes que o PCP gere ordens de compra com quantidades distorcidas.\n<b>Nota do Sistema:</b> O aviso na tela reforça que esta alteração é global para o item, afetando o histórico e o futuro da simulação.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Cadastro de Matérias-Primas</b>.\n• <b>Você envia dados para:</b> <b>PCP, Compras, WMS e Produção</b> (Atualização cadastral em tempo real).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-11 04:18:29', '2026-01-11 04:27:44'),
(33, 'professor.produtos-acabados.edit', 'EDITAR PRODUTO ACABADO (Engenharia)', '<h3>📝 Editar Produto: Ficha Técnica e Receita</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Edição de Produto é o laboratório virtual da Engenharia. Aqui o Professor (Game Master) ajusta as características comerciais e, mais importante, define a <b>\"Receita do Bolo\" (BOM - Bill of Materials)</b>. É nesta tela que você diz ao sistema: \"Para fabricar 1 Skate, eu preciso de 1 Prancha e 4 Rodas\". Sem essa configuração, o PCP não consegue calcular o que comprar e a Produção não sabe o que consumir.\n\n<b>🟣 Card: Dados Principais do Produto</b>\n\nAjustes comerciais e de planejamento:\n• <b>SKU e Nome:</b> Permite corrigir a identificação do item no catálogo.\n• <b>Preço de Venda:</b> Atualize este valor para simular inflação ou promoções de mercado.\n• <b>Tempo de Produção:</b> O ajuste deste campo altera imediatamente o cálculo de prazo de entrega para novos pedidos. Use-o para simular melhorias de processo (redução de tempo) ou máquinas lentas.\n\n<b>🟡 Card: Estrutura do Produto (Receita / BOM)</b>\n\nO coração da engenharia. Aqui você monta a lista de materiais necessária para fabricar uma unidade do produto acabado:\n• <b>Componentes Cadastrados:</b> Lista o que já faz parte da receita.\n<b>Quantidade Técnica:</b> Indica quanto de cada insumo é consumido. Ex: Se o produto é uma \"Mesa\", a receita deve ter \"4 Pés\" e \"1 Tampo\".\n<b>Ação [Remover]:</b> Desvincula um material da receita. Use com cuidado, pois afeta o cálculo do MRP.\n\n<b>➕ Seção: Adicionar Novo Componente</b>\n\nFerramenta para incluir novos insumos na receita:\n• <b>Selecione a Matéria-Prima:</b> O sistema lista apenas os materiais cadastrados e disponíveis.\n• <b>Quantidade Necessária:</b> Defina a quantia exata para fabricar 1 unidade. O sistema aceita valores decimais (ex: 0.5 kg) para processos químicos ou de corte.\n• <b>Botão [VINCULAR]:</b> Salva a relação. A partir desse momento, todo novo pedido de venda deste produto disparará automaticamente a necessidade de compra deste novo componente.\n\n<b>🧠 Dicas do Mestre (Engenharia de Processos)</b>\n\n<b>Complexidade Progressiva:</b> Comece o jogo com receitas simples (1 ou 2 componentes). Conforme a turma evolui, edite o produto e adicione mais componentes (embalagens, parafusos, adesivos) para aumentar a dificuldade do PCP e do Almoxarifado.\n<b>Auditoria de Custos:</b> Se o lucro no BI estiver baixo, verifique aqui se a receita não está \"cara demais\". Às vezes, o produto consome muita matéria-prima cara para um preço de venda baixo.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Cadastro de Matérias-Primas</b>.\n• <b>Você envia dados para:</b> <b>PCP (MRP)</b>. O cálculo de necessidade de compras depende 100% da precisão desta lista técnica.\n\nManual da Fábrica Digital - Documentação Técnica de Engenharia', '2026-01-11 04:32:21', '2026-01-11 04:32:21'),
(34, 'professor.clientes.edit', 'EDITAR CLIENTE (Manutenção de CRM)', '<h3>📝 Editar Cliente: Roteiro de Manutenção</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Edição de Cliente é a ferramenta de manutenção do CRM. O mercado é dinâmico: empresas mudam de endereço, atualizam contatos ou corrigem dados fiscais. Como <b>Game Master</b>, você utiliza esta tela para garantir a integridade dos dados que aparecerão nos pedidos de venda e nas notas fiscais emitidas pelos alunos.\n\n<b>🆔 Seção 1: Identificação do Cliente</b>\n\nCorreção dos dados principais da entidade:\n• <b>Nome / Razão Social:</b> Caso o aluno tenha cadastrado com erros de digitação, corrija aqui para manter o profissionalismo nos relatórios.\n• <b>CNPJ / CPF:</b> Dado vital para a simulação fiscal. Se este campo estiver errado, a Nota Fiscal na Expedição poderá parecer inconsistente.\n• <b>Telefone:</b> Contato comercial simulado.\n\n<b>📍 Seção 2: Localização e Sede</b>\n\nAjuste de dados logísticos. Lembre-se que o endereço do cliente define a \"rota de entrega\":\n• <b>Endereço Completo:</b> Rua, Número, Bairro.\n• <b>Cidade e Estado (UF):</b> Estes são os campos mais críticos para o BI. Se você quiser simular uma mudança de estratégia para \"Vendas Regionais\", pode alterar o estado dos clientes para concentrar a demanda em uma região específica (Ex: mudar todos para \"MG\").\n\n<b>🧠 Dicas do Mestre (Gestão de Carteira)</b>\n\n<b>Consistência Fiscal:</b> Ao editar um cliente que já possui pedidos, lembre-se que os pedidos <b>passados</b> manterão os dados antigos (histórico), mas os <b>novos</b> pedidos puxarão os dados atualizados.\n<b>Simulação de Fusões:</b> Você pode editar o nome de um cliente para simular que ele foi comprado por outra empresa, forçando os alunos de Vendas a atualizarem seus registros mentais.\n<b>Endereçamento:</b> Garanta que a sigla do Estado (UF) tenha apenas 2 letras para padronização nos relatórios.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Cadastro de Clientes</b>.\n• <b>Você envia dados para:</b> <b>Vendas</b> (Cabeçalho do Pedido) e <b>Expedição</b> (Destinatário da NF).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-11 04:36:39', '2026-01-11 04:36:39');
INSERT INTO `sistema_ajuda` (`id`, `rota`, `titulo`, `conteudo`, `created_at`, `updated_at`) VALUES
(35, 'professor.fornecedores.edit', 'EDITAR FORNECEDOR (Renegociação)', '<h3>📝 Editar Fornecedor: Roteiro de Renegociação</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Edição de Fornecedor é a ferramenta de <b>Renegociação de Contratos</b> do Game Master. Os mercados mudam: preços sobem, prazos aumentam e parceiros estratégicos podem se tornar exclusivos. Use esta tela para ajustar as condições comerciais dos fornecedores já cadastrados, impactando diretamente a estratégia de compras e o planejamento (PCP) das turmas.\n\n<b>🆔 Seção 1: Identificação e Vínculo</b>\n\nDefinição da propriedade e identidade do parceiro:\n• <b>Empresa Detentora:</b> Define quem pode ver este fornecedor.\n<b>Global:</b> Todos os alunos podem comprar dele.\n<b>Exclusivo (Alpha/Beta):</b> Apenas uma turma vê este fornecedor. Use para criar vantagens competitivas ou monopólios.\n• <b>Dados Cadastrais:</b> Correção de Razão Social e CNPJ para manter a consistência dos relatórios.\n\n<b>💰 Seção 2: Condições Comerciais (O Motor da Simulação)</b>\n\nAqui você altera as regras do jogo para o setor de Suprimentos:\n• <b>Material Fornecido:</b> Vincula o fornecedor a um insumo específico (Ex: \"Aço\").\n• <b>Preço Unitário (R$):</b> Ao alterar este valor, você simula inflação ou descontos de mercado. Isso afetará o custo dos próximos pedidos gerados pelos alunos.\n• <b>Lead Time (Dias):</b> O tempo de entrega. Aumentar este número força o PCP a planejar com maior antecedência (estoque de segurança). Diminuir este número simula um fornecedor \"Express\" (geralmente mais caro).\n\n<b>📍 Seção 3: Localização da Sede</b>\n\nDados logísticos do parceiro:\n• <b>Endereço:</b> Utilizado para simulação de frete e documentos fiscais de entrada.\n\n<b>🧠 Dicas do Mestre (Manipulação de Mercado)</b>\n<b>Choque de Oferta:</b> No meio da simulação, aumente o <b>Lead Time</b> de um fornecedor vital de 3 para 10 dias. Observe como os alunos de Compras e PCP reagem à escassez iminente.\n<b>Guerra de Preços:</b> Crie dois fornecedores para o mesmo material: um barato (entrega lenta) e um caro (entrega rápida). Edite os valores aqui para balancear a dificuldade da escolha.\n<b>Correção de Erros:</b> Se um aluno cadastrou um fornecedor com preço irreal (Ex: R$ 0,00), corrija imediatamente nesta tela para não distorcer os gráficos financeiros do BI.\n\n<b>🔗 Conexão entre Setores</b>\n• <b>Você recebe dados de:</b> <b>Cadastro de Fornecedores</b>.\n• <b>Você envia dados para:</b> <b>Compras</b> (Novas cotações usarão os novos valores) e <b>WMS</b> (Novas entregas respeitarão o novo prazo).\n\nManual da Fábrica Digital - Documentação Técnica de Cadastros', '2026-01-11 04:41:54', '2026-01-11 04:42:12'),
(36, 'aluno.pcp.analise', 'ANÁLISE MRP (Planejamento de Insumos)', '<h3>📊 Análise de Necessidades (MRP): Roteiro de Planejamento</h3>\n\n<b>1. Visão Geral do Processo</b>\n\nO MRP (Material Requirements Planning) é a ferramenta de \"Explosão de Insumos\". Nesta tela, o sistema desmembra o produto vendido em todas as peças que o compõem, baseado na Engenharia de Produto (BOM). O objetivo é identificar exatamente o que a fábrica precisa ter em mãos para cumprir a demanda, evitando que a produção comece e pare no meio por falta de componentes.\n\n<b>🔵 Seção 1: Demanda Final (O que vamos entregar?)</b>\n\nExibe o resumo do Pedido de Venda que originou este planejamento:\n• <b>Produto Acabado:</b> O item final que o cliente comprou e espera receber.\n• <b>Volume Solicitado:</b> A quantidade total que deve sair da expedição ao final do processo.\n• <b>Data de Entrega:</b> O prazo limite para que o produto esteja embalado e faturado. Se esta data estiver próxima, considere priorizar a compra dos materiais.\n\n<b>🟠 Seção 2: Explosão de Insumos (O que precisamos para fabricar?)</b>\n\nAqui o sistema revela a <b>\"Receita Técnica\"</b> do produto:\n• <b>Matéria-Prima:</b> Lista individual de cada componente necessário (ex: Prancha, Rodas).\n• <b>Qtd. Total Necessária:</b> O cálculo matemático automático (Quantidade do Pedido x Quantidade na Receita). É este número que servirá de base para o setor de <b>Compras</b> realizar as cotações.\n• <b>Unidade:</b> A métrica de consumo (kg, un, lt) para conferência com o Almoxarifado.\n\n<b>🟢 Botão: Confirmar e Gerar Ordens</b>\n\nA ação que dispara a cadeia de suprimentos:\n• Ao clicar, o sistema cria automaticamente as <b>Ordens de Produção (OP)</b> para o chão de fábrica e as <b>Ordens de Compra (OC)</b> para o setor de suprimentos.\n• <b>Atenção:</b> Esta ação é irreversível. Certifique-se de que a explosão de materiais está correta antes de confirmar.\n\n<b>🧠 Dicas do Mestre (Planejamento de Insumos)</b>\n\n<b>Conferência de Receita:</b> Verifique se a explosão faz sentido. Se um produto complexo mostrar apenas um insumo, a Engenharia de Produto pode estar incompleta no cadastro.\n<b>Antecipação de Compras:</b> O MRP é a bússola do comprador. Assim que você finaliza esta análise, o setor de Compras recebe o alerta imediato das necessidades. Sem isso, eles não sabem o que comprar.\n<b>Visão Industrial:</b> Lembre-se que o MRP foca na <b>Necessidade Bruta</b> para aquele pedido específico, garantindo que material suficiente seja alocado para esta ordem.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Vendas</b> (Pedido de Cliente) e <b>Engenharia</b> (Composição do Produto).\n• <b>Você envia dados para:</b> <b>Produção</b> (Carga de trabalho/OPs) e <b>Compras</b> (Lista de requisição/OCs).\n\nManual da Fábrica Digital - Documentação Técnica de Planejamento', '2026-01-12 00:14:06', '2026-01-12 00:45:45'),
(37, 'aluno.compras.confirmar', 'COTAÇÃO E COMPRA (Seleção de Fornecedor)', '<h3>💰 Cotação e Compra: Roteiro de Aquisição</h3>\n\n<b>1. Visão Geral do Processo</b>\n\nA tela de Cotação é o momento da verdade para o setor de Compras. Aqui você transforma uma \"Requisição\" (necessidade técnica) em um \"Pedido de Compra\" (contrato financeiro). Sua responsabilidade é analisar as opções do mercado e escolher o fornecedor que oferece o melhor equilíbrio entre <b>Preço</b> (custo) e <b>Prazo</b> (agilidade), garantindo que a fábrica não pare.\n\n<b>🟣 Card: Requisição de Compra (Detalhes da Necessidade)</b>\n\nExibe os dados técnicos do que precisa ser comprado:\n• <b>Material Solicitado:</b> O insumo exato (SKU/Nome) que o PCP pediu.\n• <b>Volume de Compra:</b> A quantidade necessária para atender à produção.\n• <b>Origem da Demanda:</b> Informa qual Venda gerou essa necessidade. Isso ajuda a identificar se é uma compra prioritária para um cliente VIP ou uma reposição de urgência.\n\n<b>⚪ Card: Análise de Mercado (Filtros de Busca)</b>\n\nFerramentas para encontrar o parceiro ideal:\n• <b>Buscar Fornecedor:</b> Permite filtrar pelo nome da empresa parceira.\n• <b>Ordenar Por:</b> Use este recurso estrategicamente.\n<b>Menor Preço:</b> Para aumentar a margem de lucro da empresa.\n<b>Menor Prazo:</b> Para salvar pedidos atrasados e evitar paradas de linha.\n\n<b>🟢 Card: Selecione o Fornecedor Vencedor</b>\n\nA lista de concorrentes homologados para fornecer este material:\n• <b>Comparativo Rápido:</b> Cada linha mostra o Nome, o Prazo de Entrega (em dias) e o Custo Total da operação.\n• <b>Seleção:</b> Clique sobre a linha do fornecedor desejado para marcá-lo como vencedor.\n• <b>Botão [ASSINAR CONTRATO]:</b> Ao confirmar, a verba é comprometida, o fornecedor é notificado e o prazo de entrega começa a contar no relógio da simulação.\n\n<b>🧠 Dicas do Mestre (Estratégia de Compras)</b>\n\n<b>Custo vs. Prazo:</b> Nem sempre o mais barato é o melhor. Se o PCP estiver com prazo apertado, pagar mais caro por uma entrega rápida pode salvar a empresa de uma multa por atraso no faturamento.\n<b>Fornecedor Exclusivo:</b> Se aparecer apenas um fornecedor na lista, significa que sua empresa tem um contrato de exclusividade ou o mercado para este item é restrito.\n<b>Reposição de Refugo:</b> Se a Origem da Demanda for \"Reposição\" ou \"Urgente\", ignore o preço e foque no prazo mais curto possível para destravar a produção.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>PCP</b> (Requisição) e <b>Cadastro de Fornecedores</b> (Tabela de Preços).\n• <b>Você envia dados para:</b> <b>WMS</b> (Aviso de recebimento futuro) e <b>Financeiro/BI</b> (Custo da operação).\n\nManual da Fábrica Digital - Documentação Técnica de Suprimentos', '2026-01-12 00:23:49', '2026-01-12 00:45:28'),
(38, 'aluno.almoxarifado.estoque', 'CONSULTA DE INVENTÁRIO (Saldo e Endereçamento)', '<h3>📋 Consulta de Inventário: Roteiro de Auditoria</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Consulta de Inventário é o <b>\"Raio-X\"</b> do Almoxarifado. Aqui você visualiza o saldo exato de cada matéria-prima e, mais importante, onde ela está fisicamente guardada. Esta ferramenta é essencial para garantir que o sistema digital reflita a realidade física do armazém (Acuracidade de Estoque).\n\n<b>⚫ Card: Estoque Atual (Painel de Saldos)</b>\nA listagem completa dos ativos da empresa:\n• <b>Barra de Busca:</b> Utilize para encontrar rapidamente um item pelo Nome ou SKU.\n• <b>Endereço (WMS):</b> O \"GPS\" do material.\n<b>Com Código (ex: R01-C02...):</b> O material está guardado na prateleira correta.\n<b>Vazio ou \"No Chão\":</b> O material foi recebido na doca mas ainda não foi endereçado. Isso é um risco operacional!\n• <b>Saldo Físico:</b> A quantidade disponível para consumo. Quando a produção solicita material, é deste saldo que o sistema desconta.\n\n<b>🧠 Dicas do Mestre (Gestão de Estoque)</b>\n\n<b>Organização:</b> Um almoxarifado sem endereços é um labirinto. Se você vir materiais sem o código WMS (botão azul na lista), vá imediatamente ao <b>Mapa de Armazenagem</b> para guardá-los.\n<b>Disponibilidade para o PCP:</b> O PCP só consegue planejar a produção se houver saldo positivo aqui. Monitore itens com saldo baixo para avisar Compras sobre a necessidade de reposição.\n<b>Auditoria:</b> Em caso de divergência (ex: a produção diz que faltou peça, mas o sistema diz que tem), esta é a tela de prova. Se está aqui, deveria estar na prateleira.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem dos Dados:</b> <b>Recebimento</b> (Entrada de Nota Fiscal).\n• <b>Destino dos Dados:</b> <b>Produção</b> (Baixa por Picking) e <b>BI</b> (Valor do Estoque).\n\nManual da Fábrica Digital - Documentação Técnica de Logística', '2026-01-12 00:32:16', '2026-01-12 00:44:58'),
(39, 'professor.monitoramento.estoque', 'CONSULTA DE INVENTÁRIO (Saldo e Endereçamento)', '<h3>📋 Consulta de Inventário: Roteiro de Auditoria</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nA tela de Consulta de Inventário é o <b>\"Raio-X\"</b> do Almoxarifado. Aqui você visualiza o saldo exato de cada matéria-prima e, mais importante, onde ela está fisicamente guardada. Esta ferramenta é essencial para garantir que o sistema digital reflita a realidade física do armazém (Acuracidade de Estoque).\n\n<b>⚫ Card: Estoque Atual (Painel de Saldos)</b>\nA listagem completa dos ativos da empresa:\n• <b>Barra de Busca:</b> Utilize para encontrar rapidamente um item pelo Nome ou SKU.\n• <b>Endereço (WMS):</b> O \"GPS\" do material.\n<b>Com Código (ex: R01-C02...):</b> O material está guardado na prateleira correta.\n<b>Vazio ou \"No Chão\":</b> O material foi recebido na doca mas ainda não foi endereçado. Isso é um risco operacional!\n• <b>Saldo Físico:</b> A quantidade disponível para consumo. Quando a produção solicita material, é deste saldo que o sistema desconta.\n\n<b>🧠 Dicas do Mestre (Gestão de Estoque)</b>\n\n<b>Organização:</b> Um almoxarifado sem endereços é um labirinto. Se você vir materiais sem o código WMS (botão azul na lista), vá imediatamente ao <b>Mapa de Armazenagem</b> para guardá-los.\n<b>Disponibilidade para o PCP:</b> O PCP só consegue planejar a produção se houver saldo positivo aqui. Monitore itens com saldo baixo para avisar Compras sobre a necessidade de reposição.\n<b>Auditoria:</b> Em caso de divergência (ex: a produção diz que faltou peça, mas o sistema diz que tem), esta é a tela de prova. Se está aqui, deveria estar na prateleira.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem dos Dados:</b> <b>Recebimento</b> (Entrada de Nota Fiscal).\n• <b>Destino dos Dados:</b> <b>Produção</b> (Baixa por Picking) e <b>BI</b> (Valor do Estoque).\n\nManual da Fábrica Digital - Documentação Técnica de Logística', '2026-01-12 00:34:52', '2026-01-12 00:46:30'),
(40, 'professor.monitoramento.mapa', 'MAPA DE ARMAZENAGEM (Endereçamento WMS)', '<h3>🗺️ Mapa de Armazenagem: Roteiro de Endereçamento</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Mapa de Armazenagem é a representação visual (Digital Twin) do seu estoque físico. Aqui, o almoxarifado deixa de ser uma lista de números e se torna um ambiente espacial tridimensional. O objetivo desta tela é realizar o \"Put-away\" (Guardagem): tirar os materiais que chegaram na doca (\"No Chão\") e alocá-los em endereços específicos para que possam ser encontrados durante a separação.\n\n<b>🟡 Navegação: Ruas (Corredores)</b>\n\nNo topo da tela, você encontra as abas de navegação (RUA 01, RUA 02...). Cada rua representa um corredor de empilhadeira.\n• <b>Estratégia:</b> Utilize ruas diferentes para segregar tipos de materiais (Ex: Rua 01 para Químicos, Rua 02 para Embalagens).\n\n<b>🏗️ Estrutura do Porta-Paletes (Coordenadas)</b>\n\nO mapa detalha a localização exata através de 4 dimensões:\n• <b>Colunas:</b> São os blocos verticais principais (Ex: COLUNA 03, COLUNA 04).\n• <b>Vãos:</b> A subdivisão lateral dentro de uma coluna (Ex: VÃO 1, VÃO 2).\n• <b>Níveis (Andares):</b> A altura da prateleira. O código <b>N1</b> fica na base, enquanto o <b>N5</b> fica no topo.\n• <b>Código de Endereço:</b> Cada posição tem um \"CEP\" único (Ex: <b>R01-C03-V1-N5</b> = Rua 1, Coluna 3, Vão 1, Nível 5).\n\n<b>🟩 Slots Vazios: \"Guardar Aqui\"</b>\n\nAs caixas com borda tracejada verde representam espaços livres na estante:\n• <b>Ação:</b> Ao clicar na seta <b>[⬇]</b>, o sistema verifica se há materiais aguardando na Doca. Se houver, ele move o material para este endereço específico.\n\n<b>⬜ Slots Ocupados: Estoque Alocado</b>\n\nAs caixas com borda sólida mostram onde seus materiais estão guardados:\n• <b>Saldo Zero:</b> Se um slot mostra o nome do produto mas quantidade \"0\", significa que o local está reservado (etiquetado) para aquele item, mas o estoque acabou.\n\n<b>🧠 Dicas do Mestre (Logística de Armazenagem)</b>\n\n<b>Curva ABC Física:</b> Guarde os materiais de maior giro (que a produção pede toda hora) nos <b>Níveis Baixos (N1 e N2)</b> e nas <b>Colunas Iniciais</b> para facilitar a pega manual.\n<b>Segurança e Peso:</b> Em uma fábrica real, colocamos materiais pesados nos níveis inferiores e leves nos níveis superiores (N4, N5). Tente simular essa lógica.\n<b>Organização:</b> Evite espalhar o mesmo material por várias Ruas diferentes. Tente concentrar o estoque para facilitar a contagem cíclica.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem:</b> <b>Checklist de Entrada</b> (Materiais recebidos na Doca).\n• <b>Destino:</b> <b>Picking / Separação</b> (O sistema usará este endereço para guiar o separador).\n\nManual da Fábrica Digital - Documentação Técnica de Logística', '2026-01-12 00:42:58', '2026-01-12 00:46:14'),
(41, 'aluno.almoxarifado.mapa', 'MAPA DE ARMAZENAGEM (Endereçamento WMS)', '<h3>🗺️ Mapa de Armazenagem: Roteiro de Endereçamento</h3>\n\n<b>1. Visão Geral do Setor</b>\n\nO Mapa de Armazenagem é a representação visual (Digital Twin) do seu estoque físico. Aqui, o almoxarifado deixa de ser uma lista de números e se torna um ambiente espacial tridimensional. O objetivo desta tela é realizar o \"Put-away\" (Guardagem): tirar os materiais que chegaram na doca (\"No Chão\") e alocá-los em endereços específicos para que possam ser encontrados durante a separação.\n\n<b>🟡 Navegação: Ruas (Corredores)</b>\n\nNo topo da tela, você encontra as abas de navegação (RUA 01, RUA 02...). Cada rua representa um corredor de empilhadeira.\n• <b>Estratégia:</b> Utilize ruas diferentes para segregar tipos de materiais (Ex: Rua 01 para Químicos, Rua 02 para Embalagens).\n\n<b>🏗️ Estrutura do Porta-Paletes (Coordenadas)</b>\n\nO mapa detalha a localização exata através de 4 dimensões:\n• <b>Colunas:</b> São os blocos verticais principais (Ex: COLUNA 03, COLUNA 04).\n• <b>Vãos:</b> A subdivisão lateral dentro de uma coluna (Ex: VÃO 1, VÃO 2).\n• <b>Níveis (Andares):</b> A altura da prateleira. O código <b>N1</b> fica na base, enquanto o <b>N5</b> fica no topo.\n• <b>Código de Endereço:</b> Cada posição tem um \"CEP\" único (Ex: <b>R01-C03-V1-N5</b> = Rua 1, Coluna 3, Vão 1, Nível 5).\n\n<b>🟩 Slots Vazios: \"Guardar Aqui\"</b>\n\nAs caixas com borda tracejada verde representam espaços livres na estante:\n• <b>Ação:</b> Ao clicar na seta <b>[⬇]</b>, o sistema verifica se há materiais aguardando na Doca. Se houver, ele move o material para este endereço específico.\n\n<b>⬜ Slots Ocupados: Estoque Alocado</b>\n\nAs caixas com borda sólida mostram onde seus materiais estão guardados:\n• <b>Saldo Zero:</b> Se um slot mostra o nome do produto mas quantidade \"0\", significa que o local está reservado (etiquetado) para aquele item, mas o estoque acabou.\n\n<b>🧠 Dicas do Mestre (Logística de Armazenagem)</b>\n\n<b>Curva ABC Física:</b> Guarde os materiais de maior giro (que a produção pede toda hora) nos <b>Níveis Baixos (N1 e N2)</b> e nas <b>Colunas Iniciais</b> para facilitar a pega manual.\n<b>Segurança e Peso:</b> Em uma fábrica real, colocamos materiais pesados nos níveis inferiores e leves nos níveis superiores (N4, N5). Tente simular essa lógica.\n<b>Organização:</b> Evite espalhar o mesmo material por várias Ruas diferentes. Tente concentrar o estoque para facilitar a contagem cíclica.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem:</b> <b>Checklist de Entrada</b> (Materiais recebidos na Doca).\n• <b>Destino:</b> <b>Picking / Separação</b> (O sistema usará este endereço para guiar o separador).\n\nManual da Fábrica Digital - Documentação Técnica de Logística', '2026-01-12 00:44:23', '2026-01-12 00:44:39'),
(42, 'aluno.expedicao.conferir', 'CONFERÊNCIA DE EXPEDIÇÃO (Faturamento)', '<h3>🚚 Conferência de Expedição: Roteiro de Faturamento</h3>\n\n<b>1. Visão Geral do Processo</b>\n\nA Conferência de Expedição é o <b>\"Ponto de Não Retorno\"</b> da simulação. Nesta tela, você valida se a fábrica realmente cumpriu o que foi prometido ao cliente. O faturamento só é autorizado se houver saldo físico disponível no estoque de Produtos Acabados. Ao confirmar, você oficializa a venda, emite a Nota Fiscal e encerra o ciclo operacional do pedido.\n\n<b>🟣 Cabeçalho: Identificação do Contrato</b>\n\nConfirmação dos dados mestres:\n• <b>Pedido e Cliente:</b> Certifique-se de que está faturando para o cliente correto.\n• <b>Status:</b> Indica que o pedido está na fase de conferência (\"Em Conferência\").\n<b>📦 Card: Itens e Disponibilidade (Checklist de Saída)</b>\nA tabela cruza a demanda comercial com a realidade física:\n• <b>Solicitado:</b> A quantidade que o cliente comprou.\n• <b>Estoque Real:</b> O saldo que o setor de <b>Embalagem</b> efetivamente entregou e lacrou no depósito. Se este número for menor que o solicitado, houve falha na produção.\n• <b>A Faturar:</b> Quantidade que será descontada do estoque e inserida na Nota Fiscal. O sistema sugere automaticamente o máximo disponível.\n• <b>Status [COMPLETO]:</b> Sinaliza que a produção atingiu 100% da meta.\n\n<b>🟢 Botão: Emitir Nota Fiscal (Faturamento)</b>\nA ação final da cadeia logística:\n• <b>Baixa de Estoque:</b> No momento do clique, os produtos saem fisicamente do seu armazém virtual.\n• <b>Geração de Receita:</b> O valor total da nota é computado no BI (Torre de Controle) como faturamento realizado.\n• <b>Data de Emissão:</b> A nota sairá com a data e hora atuais do jogo.\n\n<b>🧠 Dicas do Mestre (Estratégia de Saída)</b>\n<b>Sincronismo com WMS:</b> Se o \"Estoque Real\" estiver zerado ou menor que o \"Solicitado\", verifique no Monitor se o setor de Embalagem já lacrou o lote. Pedidos não embalados não aparecem aqui.\n<b>Faturamento Parcial:</b> O sistema permite faturar menos do que o solicitado se não houver estoque, mas isso gerará um \"Saldo de Backlog\" e prejudicará seu indicador de OTIF (Pedidos entregues completos).\n<b>Bloqueios de TI:</b> Fique atento ao Painel do Caos. Se o sistema de faturamento for sabotado pelo Professor, você não conseguirá clicar no botão de emitir nota.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Você recebe dados de:</b> <b>Embalagem</b> (Produtos Prontos) e <b>Vendas</b> (Dados do Cliente).\n• <b>Você envia dados para:</b> <b>Visão Executiva (BI)</b>, registrando o lucro e o sucesso da entrega.\n\nManual da Fábrica Digital - Documentação Técnica de Expedição', '2026-01-12 00:50:58', '2026-01-12 00:50:58'),
(43, 'aluno.almoxarifado.recusar', 'RECUSA DE RECEBIMENTO (WMS)', '<h3>🚫 Recusa de Recebimento: Roteiro de Devolução</h3>\n\n<b>1. Visão Geral do Processo</b>\n\nA tela de Recusa é o procedimento de segurança do Almoxarifado. Quando uma carga chega com avaria física, erro de nota fiscal ou qualquer não-conformidade técnica, ela não pode entrar no estoque. O WMS deve barrar a entrada e devolver o material ao fornecedor. Esta ação dispara um alerta automático para o setor de Compras, que terá que providenciar uma reposição urgente para não parar a fábrica.\n\n<b>🔴 Card: Devolução de Mercadoria (Registro de NC)</b>\n\nO formulário oficial de rejeição:\n• <b>Item Rejeitado:</b> Confirme se o material que está sendo devolvido é realmente o que consta na tela.\n• <b>Fornecedor Responsável:</b> Identifica quem enviou a carga defeituosa. Essa informação é vital para a avaliação de qualidade do fornecedor no BI.\n\n<b>⚠️ Laudo do Controle de Qualidade (Apenas em Casos de Caos)</b>\n\nSe o Professor injetou uma falha programada, este box preto aparecerá:\n• <b>Ocorrência Detectada:</b> A descrição técnica do problema (Ex: \"Embalagem violada\").\n• <b>Instrução:</b> O sistema obriga você a copiar essa justificativa no motivo da recusa. Isso simula o recebimento de um laudo técnico da equipe de qualidade.\n\n<b>📝 Motivo Técnico da Recusa</b>\n\nCampo obrigatório para formalizar a devolução:\n• <b>Descrição Clara:</b> Escreva o motivo real (ex: \"Caixa molhada\", \"Quantidade incorreta\").\n• <b>Impacto:</b> Lembre-se que o comprador lerá essa mensagem para entender o que aconteceu e cobrar o fornecedor.\n\n<b>🧠 Dicas do Mestre (Gestão de Conflitos)</b>\n\n<b>Consequência Imediata:</b> Ao clicar em <b>[Confirmar Recusa]</b>, a produção ficará sem material. Compras será comunicada imediatamente para que eles saibam que houve Recusa e refaçam a compra novamente.\n<b>Custo da Recusa:</b> Devolver material gera custo logístico e atraso. Só recuse se for estritamente necessário ou se o sistema indicar uma Inconformidade Programada.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem:</b> <b>Doca de Recebimento</b>.\n• <b>Destino:</b> <b>Compras</b> (Alerta de Reposição) e <b>BI</b> (Registro de Custo de Ineficiência).\n\nManual da Fábrica Digital - Documentação Técnica de Logística', '2026-01-12 01:03:26', '2026-01-12 01:03:26'),
(44, 'aluno.almoxarifado.separar', 'SEPARAÇÃO DE MATERIAIS (Picking)', '<h3>📤 Separação de Materiais: Roteiro de Picking</h3>\n\n<b>1. Visão Geral do Processo</b>\n\nO Picking (ou Separação) é a atividade de retirar materiais do estoque para atender a uma necessidade específica da fábrica. Quando a Produção solicita insumos, o sistema gera uma \"Ordem de Separação\". Sua missão nesta tela é localizar fisicamente onde o material está guardado e enviá-lo para a linha de montagem.\n\n<b>🟣 Card: Ação Necessária (Ordem de Serviço)</b>\n\nO painel superior indica a tarefa imediata:\n• <b>Quantidade e Item:</b> Mostra exatamente o que você deve buscar (Ex: 1,00 un de Prancha).\n• <b>Foco Visual:</b> O sistema destaca o nome do material para evitar erros de leitura.\n\n<b>🗺️ Mapa de Localização (Navegação Guiada)</b>\n\nO WMS ajuda você a encontrar o item no armazém:\n• <b>Ruas:</b> Observe as abas no topo do mapa. A rua onde o material está guardado estará marcada com um <b>Ponto Vermelho</b> ou destaque. Clique nela para entrar.\n• <b>Alvo Piscando:</b> Dentro da rua, procure pela caixa (slot) que está <b>Piscando</b> com uma borda colorida. Este é o endereço exato (Rua-Coluna-Vão-Nível) do material.\n\n<b>🎯 Ação de Retirada</b>\n\nAo encontrar a prateleira correta:\n• <b>Conferência de Saldo:</b> O slot mostra quanto material existe lá (Ex: 11 un). Verifique se há saldo suficiente para atender o pedido.\n• <b>Ícone de Alvo:</b> Clique no ícone de <b>[Mira / Alvo]</b> no canto da caixa para confirmar a retirada.\n• <b>Baixa Automática:</b> Ao clicar, o sistema subtrai a quantidade pedida do estoque e muda o status da solicitação para \"Entregue\".\n\n<b>🧠 Dicas do Mestre (Logística de Saída)</b>\n\n<b>Não Erre o Endereço:</b> O sistema bloqueia a retirada se você tentar clicar na caixa errada. Isso simula a leitura de código de barras (bipagem) incorreta na vida real.\n<b>Agilidade:</b> A Produção está parada esperando esse material. Quanto mais rápido você localizar e confirmar, menor será o tempo de máquina parada.\n<b>Endereçamento Vazio:</b> Se o sistema pedir para separar um item mas não indicar o local (nenhuma luz piscando), significa que o material está \"No Chão\" (sem endereço) ou o estoque virtual está zerado (erro de inventário).\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem:</b> <b>Produção</b> (Quem solicitou).\n• <b>Destino:</b> <b>Chão de Fábrica</b> (Onde o material será consumido).\n\nManual da Fábrica Digital - Documentação Técnica de Logística', '2026-01-12 01:10:30', '2026-01-12 01:10:30'),
(45, 'aluno.producao.apontar', 'APONTAMENTO DE PRODUÇÃO (Finalização de Lote)', '<h3>🏭 Apontamento de Produção: Roteiro de Finalização</h3>\n\n<b>1. Visão Geral do Processo</b>\n\nO Apontamento é o registro oficial do resultado da fabricação. É nesta tela que o operador confirma quantas peças foram produzidas com sucesso e quantas foram perdidas (refugo). Este dado é crucial porque atualiza o estoque de produtos acabados e encerra o ciclo de tempo da máquina (Lead Time).\n\n<b>🟣 Cabeçalho: Resumo da Meta</b>\n\nDados de controle da Ordem de Produção (OP):\n• <b>Produto Alvo:</b> O item que está sendo fabricado.\n• <b>Meta Total:</b> A quantidade original solicitada pelo PCP.\n• <b>Saldo a Fazer:</b> Quantas peças faltam para encerrar esta ordem.\n\n<b>✅ Quantidade Aprovada (Verde)</b>\n\nIndica o volume de produção com qualidade 100%:\n• <b>Entrada no Estoque:</b> Este número será transferido imediatamente para o setor de <b>Embalagem</b> para conferência final.\n• <b>Eficiência:</b> Em condições normais, este valor deve ser igual ao saldo a fazer.\n\n<b>🗑️ Refugo / Perda (Vermelho)</b>\n\nIndica o volume de material desperdiçado durante o processo:\n• <b>Laudo Técnico:</b> Se o Professor (Game Master) inseriu uma falha na máquina (Sabotagem), este campo virá preenchido automaticamente com a quantidade perdida.\n• <b>Consequência:</b> Ao confirmar um apontamento com refugo, o sistema dispara automaticamente uma <b>Requisição de Compra Urgente</b> para repor o material perdido, e a OP permanece aberta aguardando essa reposição.\n\n<b>🧠 Dicas do Mestre (Chão de Fábrica)</b>\n\n<b>Operação Guiada:</b> Note que os campos são bloqueados para edição. O simulador calcula o resultado baseado no status da máquina. Sua função é validar e confirmar o apontamento.\n<b>Ciclo de Reposição:</b> Se houver refugo, não se desespere. Confirme a perda para que o setor de Compras seja avisado. A produção só poderá continuar quando o novo material chegar.\n<b>Encerramento:</b> Ao clicar em <b>[Confirmar Entrada]</b>, a máquina é \"desligada\" e o custo de produção é calculado no BI.\n\n<b>🔗 Conexão entre Setores</b>\n• <b>Origem:</b> <b>Máquina em Operação</b>.\n• <b>Destino:</b> <b>Embalagem</b> (Produtos Bons) e <b>Compras</b> (Solicitação de Reposição de Refugo).\n\nManual da Fábrica Digital - Documentação Técnica de Produção', '2026-01-12 01:16:35', '2026-01-12 01:16:35'),
(46, 'dashboard', 'PORTARIA (Aguardando Alocação)', '<h3>⏳ Portaria: Aguardando Posto de Trabalho</h3>\n<b>1. Visão Geral</b>\n\nVocê está no <b>Hall de Entrada</b> da Fábrica Digital. Esta tela indica que seu cadastro no \"Banco de Talentos\" foi realizado com sucesso e você já possui credenciais de acesso válidas. No entanto, o seu usuário ainda não foi \"contratado\" para atuar em nenhuma empresa específica. Você está na lista de espera.\n\n<b>🆔 Card: Acesso Autorizado</b>\n\nConfirmação de identidade:\n• <b>Identificação:</b> Confirme se o nome exibido é o seu.\n• <b>Status:</b> O ícone da ampulheta indica que o sistema está aguardando uma ação externa (do Professor) para liberar seus menus de trabalho.\n\n<b>🟦 Botão: Verificar Novamente</b>\n\nSua única ação neste momento:\n• <b>Atualizar Status:</b> Ao clicar neste botão, o sistema verifica no banco de dados se o Game Master já realizou a sua escalação.\n• <b>Resultado:</b> Se você já tiver sido alocado, esta tela desaparecerá e você será redirecionado automaticamente para o Painel de Operações da sua nova empresa.\n\n<b>🧠 Dicas para o Aluno</b>\n\n<b>Não é um Erro:</b> Ficar parado nesta tela é normal no início da aula. Significa apenas que o Professor ainda está montando as equipes.\n<b>Comunicação:</b> Avise ao Professor que você já criou a conta e está \"Na Portaria\" aguardando a definição do seu cargo (Vendas, Produção, etc).\n<b>Aguarde:</b> Não crie outra conta. Apenas espere a liberação.\n\n<b>🔗 Conexão entre Setores</b>\n\n• <b>Origem:</b> <b>Cadastro/Login</b>.\n• <b>Destino:</b> <b>Qualquer Setor Operacional</b> (Assim que o Professor definir sua função na tela de Equipes).\n\nManual da Fábrica Digital - Documentação Técnica de Acesso', '2026-01-12 02:30:41', '2026-01-12 02:32:00');

