--
-- Estrutura para tabela `solicitacoes_separacao`
--

CREATE TABLE `solicitacoes_separacao` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `ordem_producao_id` bigint(20) UNSIGNED NOT NULL,
  `materia_prima_id` bigint(20) UNSIGNED NOT NULL,
  `quantidade_solicitada` decimal(10,2) NOT NULL,
  `aluno_solicitante_id` bigint(20) UNSIGNED NOT NULL,
  `status` varchar(255) NOT NULL DEFAULT 'Pendente',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

